// 简体中文 for the instrument catalog (cultures/instruments/ancient-americas.js), keyed by entry id.
Object.assign(I18N["zh-CN"].instruments, {
"memet": { sound: "响亮、带簧片味的嗡鸣音色，像带鼻音的单簧管；两根音高略有差异的管子互相拍音，使声音闪烁摇曳。起音尖锐，配合循环换气可连绵不断。", range: "较窄，每根管约五度至八度。", tuning: "由指孔固定；古埃及管的实际音阶不明。", acoustics: "气息 → 单片同体芦苇簧片拍击管壁 → 圆柱形芦苇管腔（两根并列）。", materials: "两根等长芦苇用绳或树脂捆在一起，同体簧片切自小段芦苇管。", making: "由干芦苇切制；在一小段闭口芦苇管上切出舌片作簧片，再用绳或树脂把两管捆扎。", usage: "两管并持同时吹奏，双手手指按住对应的孔，使两个音互相拍击。", role: "在持续低音上奏旋律，或奏两条平行旋律线。", players: "职业乐师，男女皆有，见于宴会和劳作场景。", skills: "循环换气以保持声音不断；两管之间的轻微失谐带来丰满的拍音。", scenes: "墓室壁画中描绘的宴会、收获劳作和舞蹈。", origin: "古埃及，古王国墓室浮雕中已出现平行双管。", finds: "萨卡拉古王国墓室浮雕（约公元前2500年）描绘了平行双管；后期埃及墓葬中有芦苇管实物留存。", history: "两根芦苇管并排捆扎、各带一枚单簧片，自古王国起即有演奏；同样的设计保留在埃及的 zummāra زمارة 和 arghūl أرغول 中。", variants: "留存为埃及的 zummāra（两根旋律管）和 arghūl（一根长低音管）。", today: "这一设计延续在埃及民间音乐的 zummāra 和 arghūl 中。", uncertain: "古代管是否使用单簧片是由现代后裔推断的；没有簧片实物留存。", techniques: [{ name: "低音与旋律拍音", how: "两管同时按指，音高略有差异而互相拍击，形成嗡鸣摇曳的音色。" }, { name: "循环换气", how: "用鼻吸气的同时以腮部把空气压出，使簧片的声音不间断。" }] },
"benet": { sound: "温暖柔和的羊肠弦音色，拨弦迅疾，余音适中；轻柔得足以为独唱伴奏。制音后的音短而干。", range: "较大的竖琴可能约两个八度；确切音高不明。", tuning: "通过在琴颈上扭转或滑动琴弦来调音；所用音阶不明。", acoustics: "手指拨弦 → 羊肠弦 → 蒙皮木制共鸣箱。", materials: "弯曲的木制琴颈插入蒙皮的中空木共鸣箱，羊肠弦系在琴颈上。", making: "由神庙和宫廷的木工制作：弯曲的琴颈插入蒙兽皮的中空箱体，琴弦用绳系在琴颈上以便调音。", usage: "跪姿或站姿演奏，双手拨弦；共鸣箱置于地面或肩上。", role: "为歌唱伴奏；奏旋律和双音。", players: "神庙与宫廷的竖琴师，早期多为男性，包括盲人竖琴师；宴会场景中也有女性演奏。", skills: "双手拨弦、制音，并如墓室场景所示奏四度和五度的双音。", scenes: "神庙仪式、宴会以及《竖琴手之歌》等丧葬歌曲。", repertoire: "刻于墓中的《竖琴手之歌》，如英特夫王墓的歌。", meaning: "与宴饮、来世和对亡者的追思相关。", origin: "古埃及，自古王国（约公元前2500年）起。", finds: "自古王国（约公元前2500年）起即有描绘；拉美西斯三世墓（KV11，约公元前1150年）中的彩绘大竖琴；实物保存在卢浮宫等博物馆。", history: "起初是小型的肩扛或弓形竖琴；到新王国时期，竖琴师也演奏高大的立式弓形竖琴，其上彩绘镶嵌华丽，如拉美西斯三世墓中的大竖琴。", variants: "小型肩扛竖琴、勺形竖琴和大型立式弓形竖琴。", today: "在埃及已绝迹；弓形竖琴的设计延续在乌干达的 adungu 及其他非洲竖琴中。", techniques: [{ name: "双手拨弦", how: "双手从两侧拨弦，得到温暖的羊肠弦音色。" }, { name: "制音", how: "用手按住仍在振动的琴弦使其停止，留下短而干的音。" }] },
"sebi": { sound: "带气息的、空灵而空洞的音色，起音柔和，音周围有很多风声，音量轻柔亲密。改变角度可使音高平滑弯曲。", range: "加上超吹约两个八度。", tuning: "由少数指孔的位置决定；古代音阶不明。", acoustics: "气息 → 气流在锐利的敞口边缘被劈开 → 敞口圆柱形芦苇管。", materials: "一段开有几个指孔的芦苇或芦秆。", making: "由笔直的芦苇切成，沿管身烧出或钻出孔；由演奏者自制。", usage: "倾斜着向一侧持握，演奏者对着顶端锐利的边缘吹气。", role: "旋律。", players: "牧人，以及宴会和神庙的职业乐师。", skills: "以唇与角度控制微调音高；带气息、空灵的起音。", scenes: "牧人的音乐、宴会和神庙合奏。", origin: "古埃及及更广阔的近东，自古王国起即有长的边缘吹奏芦苇笛的描绘。", finds: "见于古王国浮雕，例如萨卡拉的嫩凯夫卡墓（约公元前2500年）；后期墓葬中有芦苇笛留存。", history: "一种细长的芦苇笛，对着敞开的上缘吹奏、斜持；是阿拉伯与波斯 ney（奈伊笛）的祖先。", variants: "有长短两种；后裔是阿拉伯与波斯的 ney 以及埃及的 kawala。", today: "它的直系后裔 ney 和 kawala 仍是活态乐器。", techniques: [{ name: "斜持边缘吹奏", how: "斜持笛身，让气流吹过锐利的上缘，得到带气息、空灵的音色。" }, { name: "音高微调", how: "改变嘴唇覆盖边缘的面积和角度，使音高平滑弯曲。" }] },
"sesheshet": { sound: "干脆清脆的金属沙沙与叮当声，起音尖锐，衰减极短；连续摇动时模糊成闪烁的沙沙声。", range: "无固定音高，明亮而高。", acoustics: "摇动 → 松动的金属杆和圆片撞击框架 → 无共鸣体。", materials: "装在手柄上的青铜或铜框，松套的金属杆上穿有发出叮当声的圆片。", making: "由神庙金属工匠铸造或锤制，用青铜或铜；神龛形的也有以釉砂（费昂斯）制成的还愿物。", usage: "握住手柄，以短促的脉冲式摇动，使杆与圆片发出声响。", role: "节奏与仪式之声。", players: "女祭司、神庙歌者和高阶层女性，尤其见于哈托尔和伊西斯的崇拜中。", skills: "随歌舞节奏摇动，常与作为第二件响器的 menat 项链同用。", scenes: "哈托尔和伊西斯的神庙仪式、游行和收获歌。", meaning: "为哈托尔所钟爱；其沙沙声据说像风吹过纸莎草，能安抚或平息诸神。", origin: "古埃及，属于女神哈托尔；米诺斯克里特的收获者瓶上也描绘有叉铃。", finds: "自古王国起即有描绘；新王国及以后留存许多青铜叉铃；哈吉亚·特里亚达出土的米诺斯收获者瓶（约公元前1500年）上绘有叉铃。", history: "埃及有神龛形和环形两种叉铃；环形随伊西斯崇拜传遍罗马世界，并以 ṣänaṣəl 之名保留在埃塞俄比亚教会中。", variants: "神龛形（naos）叉铃与环形（sekhem）叉铃；罗马的伊西斯叉铃；埃塞俄比亚的 ṣänaṣəl ጸናጽል。", today: "仍在埃塞俄比亚和厄立特里亚正教会中以 ṣänaṣəl 之名使用；其余已成历史。", techniques: [{ name: "脉冲式摇动", how: "配合舞蹈或歌唱摇动，各部件撞击出干脆利落的节奏。" }, { name: "连续摇动", how: "不停地快速摇动，叮当声模糊成持续闪烁的沙沙声。" }] },
"sheneb": { sound: "粗犷响亮的嘹亮号声，起音硬，音色粗糙带鼻音的铜管味；只有一两个可用的音。", range: "两三个自然音；图坦卡蒙的号大约在 C4 和 D♭4 一带的基音。", tuning: "由管长决定；没有音阶，只有信号音。", acoustics: "唇振 → 短的圆锥-圆柱形金属管内的气柱 → 喇叭口。", materials: "锤打成的银、青铜或铜管，带喇叭口，有时配有木芯加以保护。", making: "用银片或青铜片锤制，接缝处焊合；不用时以木芯保护薄薄的管身。", usage: "以唇在窄端振动吹奏，只能吹出少数几个响亮的音。", role: "信号。", players: "军中号手和神庙官员。", skills: "以唇振出少数几个泛音；有力的信号呼号。", scenes: "军事游行与信号、宗教游行。", meaning: "与战神和奥西里斯相关；人们认为号声能召唤诸神参战。", origin: "古埃及；图坦卡蒙墓（约公元前1325年）出土的两支号是最著名的例子。", finds: "图坦卡蒙墓（约公元前1325年）出土的两支号，一银一铜，1939年曾在 BBC 广播中吹奏。", history: "一种短直号，用于军事信号和奥西里斯崇拜；图坦卡蒙的号一银一铜，是现存最古老的可吹奏号之一。", variants: "银制和青铜制两种。", today: "已成历史；原件藏于开罗埃及博物馆。", uncertain: "可吹奏的音域存在争议，因为1939年的录音使用了现代号嘴。", techniques: [{ name: "信号呼号", how: "唇在窄端振动，发出一声响亮的铜管号声。" }, { name: "泛音间的唇滑奏", how: "收紧嘴唇，音色不间断地跳到上一个自然泛音。" }] },
"barrel-drum": { sound: "较大的鼓面发出低沉、圆润、开放的咚声，较小的鼓面发出更尖锐明亮的拍击声；起音强，共鸣适中。", range: "无固定音高，中低。", acoustics: "手击 → 绑缚的皮鼓面 → 长木桶形鼓身。", materials: "木制鼓身，两张皮面用绳索绑在一起。", making: "把原木掏空成桶形，两张生皮鼓面用绳索绑缚在鼓身上。", usage: "用带子挂着，双手击打两面鼓面。", role: "节奏。", players: "士兵和游行中的鼓手。", skills: "双手击打两面鼓面，奏出低音和高音击法。", scenes: "军事行进、游行和节庆。", origin: "古埃及，自中王国起。", finds: "自中王国起即有描绘；贝尼哈桑出土有绑缚式桶鼓实物（约公元前2000年）。", history: "一种水平悬挂的长双面鼓，用于游行和军中；留存的实物鼓面是绳索绑缚的。", today: "已成历史；双面桶鼓在埃及民间音乐中仍很常见。", techniques: [{ name: "低音鼓面击法", how: "平掌击打较大的低音鼓面，得到深沉开放的音色。" }, { name: "高音鼓面击法", how: "用手指击打另一面较高的鼓面，得到更尖锐明亮的拍击声。" }] },
"long-lute": { sound: "明亮、单薄、带弹拨感的拨弦音，衰减快；扫弦时发出轻快的节奏性嗡声。", range: "两三根弦，约一个半八度。", tuning: "羊肠弦以系结或弦轴调音；可能按四度或五度定弦，但古代的定弦不明。", acoustics: "拨片拨弦 → 羊肠弦 → 蒙皮的小琴身。", materials: "蒙皮的小型木制或龟甲琴身，长木琴颈和羊肠弦，末端常带流苏。", making: "小型木制或龟甲琴身，面板蒙皮，长木琴颈贯穿其中（串刺式鲁特）。", usage: "横置于身前，用拨片拨弦，左手沿琴颈按弦。", role: "旋律与节奏。", players: "艺人和舞者，男女皆有。", skills: "拨片扫弦，以及在无品琴颈上的旋律跑动。", scenes: "宴会、舞者和艺人。", origin: "美索不达米亚（阿卡德时期，约公元前2300年），传播到安纳托利亚、黎凡特和新王国埃及。", finds: "阿卡德圆筒印章（约公元前2300年）；赫梯浮雕；新王国埃及墓室壁画和留存的鲁特琴，如乐师哈尔莫斯的琴（约公元前1500年）。", history: "琴身小、琴颈极长，有两三根弦，见于阿卡德印章、赫梯浮雕和埃及墓室壁画；它是后世西亚长颈鲁特琴的祖先之一。", variants: "有两弦和三弦形式；后来有希腊的潘杜拉（pandoura）以及西亚和中亚的长颈鲁特琴。", today: "已成历史；其家族延续为 tanbur、萨兹（saz）和冬不拉（dombra）。", techniques: [{ name: "拨片弹奏", how: "用拨片在无品琴颈上弹出单音，得到明亮带弹拨感的旋律线。" }, { name: "拨片扫弦", how: "拨片刷过所有琴弦，奏出节奏性的和弦。" }, { name: "沿琴颈滑音", how: "左手手指沿无品琴颈滑动，在音高之间滑行。" }] },
"cello": { sound: "丰润温暖、如歌唱般接近人声的音色，低音弦深沉饱满，A 弦明亮而强烈；拨奏发出圆润共鸣的“嘣”声。", range: "C2 至约 A5，超过三个半八度。", tuning: "C2–G2–D3–A3，五度定弦；可按平均律演奏，在阿拉伯音乐中则按 maqam 的四分音演奏。", acoustics: "弓（涂松香的马尾）→ 钢弦或羊肠弦 → 琴马 → 云杉与枫木制成的琴箱。", materials: "云杉与枫木琴身，乌木指板，四根弦，一根尾钉和一把马尾弓。", making: "由制琴师以雕刻的云杉面板、枫木背板、侧板和琴颈制成，配乌木指板。", usage: "坐着演奏，琴身夹于双膝之间，可拉弓或拨弦。", role: "低音与次中音旋律。", players: "管弦乐和室内乐乐手；埃及 firqa（乐团）的大提琴手。", skills: "揉弦、拇指把位、拨弦以及长时间持续的低音线条。", scenes: "管弦乐团、室内乐和埃及的 firqa。", repertoire: "巴赫的大提琴组曲；在埃及则是乌姆·库勒苏姆的乐团。", origin: "16世纪的意大利，作为小提琴家族的低音成员。", finds: "早期低音小提琴出现在16世纪意大利绘画中；安德烈亚·阿马蒂制作了一些最早的现存实例（约1550年代至1570年代）。", history: "17至18世纪由低音小提琴发展成现代大提琴；20世纪开罗的广播和电影乐团把它加入阿拉伯 firqa。", variants: "巴洛克大提琴（羊肠弦，无尾钉）、五弦的小大提琴（cello piccolo）。", today: "全世界广泛演奏。", techniques: [{ name: "拉弓", how: "弓在弦上拉过，得到持续如歌的音色。" }, { name: "拨奏", how: "用手指拨弦，得到圆润、短促而有共鸣的音。" }, { name: "跳弓", how: "弓在弦上弹跳，奏出短促、轻巧而分离的音。" }, { name: "弓杆击弦", how: "用弓杆的木质部分敲击琴弦，得到干脆的敲击音。" }, { name: "自然泛音", how: "手指轻触弦上的节点，得到纯净如长笛的泛音。" }] },
"double-bass": { sound: "深沉暗淡的木质音色，既可听见也可感受；拉奏时低吼，拨奏时是圆润、沉闷并快速绽放的音。", range: "E1 至约 G4（实际音高），超过三个八度。", tuning: "E1–A1–D2–G2，四度定弦；一些五弦低音提琴增加一根低音 B 或 C 弦。", acoustics: "弓或手指 → 粗弦 → 琴马 → 大型云杉与枫木琴身。", materials: "大型木制琴身，斜肩，长琴颈，四根（有时五根）粗弦和一根尾钉。", making: "由制琴师制作，常沿用古提琴传下来的平背和斜肩。", usage: "站着或坐在高凳上演奏，可用手指拨弦或拉弓。", role: "低音。", players: "管弦乐、爵士、蓝草音乐和 firqa 的乐手。", skills: "行走低音线条、弦乐队中的击弦，以及拉弓演奏。", scenes: "管弦乐团、蓝草与老式乐队、爵士乐和阿拉伯乐团。", repertoire: "管弦乐低音声部、爵士乐中的行走低音、蓝草和摇滚复古乐（rockabilly）中的击弦低音。", origin: "16至17世纪的欧洲，出自古提琴和小提琴家族的 violone。", history: "成为管弦乐团的低音；拨奏时它是弦乐队、蓝草和爵士乐的根基，20世纪开罗的 firqa 也采用了它。", variants: "三弦、四弦和五弦低音提琴；管弦乐与爵士的不同装置。", today: "全世界广泛演奏。", techniques: [{ name: "拉弓", how: "弓在粗弦上拉过，得到深沉持续的音色。" }, { name: "拨奏", how: "用指侧拨弦，得到圆润轰鸣的行走低音。" }, { name: "击弦低音", how: "把弦拉离指板再让它弹回拍击，给每个音增添打击式的“啪”声。" }, { name: "跳弓", how: "短促的弹跳弓法奏出轻巧、断开的低音。" }, { name: "泛音", how: "轻触弦上节点，得到高而清透如玻璃的泛音。" }] },
"sagat": { sound: "张开拍击时是明亮高亢的“叮”声，合拢时是干脆的咔嗒声；轻盈而穿透。", range: "无固定音高，非常高而明亮。", acoustics: "相互拍击 → 小黄铜圆盘振动 → 无共鸣体。", materials: "黄铜圆盘，配套戴在手指上的弹性带。", making: "铸造或冲压的黄铜，开有穿弹性指带的槽口。", usage: "每只手戴一副，共两副，以节奏型式相互敲击。", role: "节奏。", players: "肚皮舞者和舞厅乐手；也有 zār 仪式的演奏者。", skills: "快速交替击打，奏出开放的鸣响和闷住的咔嗒声。", scenes: "舞蹈（raqs sharqi）、zaffa 婚礼游行、民间合奏。", repertoire: "maqsūm 和 malfūf 等 raqṣ sharqī（东方舞）节奏。", origin: "埃及与阿拉伯世界；小型指钹可追溯到古代地中海。", finds: "古代指钹和摇铃（crotal）见于埃及和罗马世界。", history: "一对对戴在拇指和中指上的小钹，是古代 crotal 的延续；如今与舞蹈紧密相连。", variants: "有多种尺寸：小型舞蹈用 zills 和较大的 zār 钹。", today: "仍在使用。", techniques: [{ name: "开放鸣响击法", how: "钹片相击后立刻分开，发出明亮的金属鸣响。" }, { name: "闷音咔嗒", how: "击后把钹片压在一起，发出短促的闷响。" }, { name: "快速交替", how: "双手快速交替击打，奏出连续的叮当滚奏。" }] },
"mizmar": { sound: "响亮、尖锐、带鼻音和嗡鸣的音色，适合户外，起音硬，借循环换气声音持续不断；装饰音听来如急促的哀号。", range: "约一个半八度。", tuning: "指孔固定；演奏 Ṣabā、Rāst 等阿拉伯 maqāmāt，中立音程由嘴唇调节。", acoustics: "气息 → 松松含在口中、顶着唇盘的双簧片 → 圆锥形木制管腔和喇叭口。", materials: "车制的圆锥形木管身，带喇叭口，金属管碗上装双簧片，另有唇盘。", making: "由民间工匠以杏木或其他木料车制；簧片由演奏者用芦苇自制。", usage: "簧片整个含入口中，嘴唇抵在唇盘上；鼓起腮帮大声吹奏。", role: "旋律，常由数支 mizmar 组成乐队，其中一支奏持续低音。", players: "上埃及的职业民间乐师，常为世袭家族。", skills: "循环换气以保持声音连续，奏带装饰的 maqam 旋律。", scenes: "上埃及的婚礼、圣徒节（mulid）和 tahtib 棍舞。", repertoire: "Saʿīdī 音乐、taḥṭīb 棍舞和马舞；Mizmar Baladi 合奏。", origin: "上埃及（Ṣaʿīd）及更广阔的阿拉伯世界，属于民间唢呐类乐器。", history: "一种圆锥形双簧唢呐，长期与大型 tabl 鼓一起在户外演奏；上埃及的 Mizmar Baladi 合奏因它而闻名。", variants: "尺寸从高音的 sibs 到低音、更长的 tiṣ mizmar 不等。", today: "仍在使用；Les Musiciens du Nil 等 Mizmar Baladi 合奏团在国际巡演。", techniques: [{ name: "循环换气", how: "腮部压出空气，同时用鼻吸气，使响亮带簧片味的音色永不中断。" }, { name: "装饰颤音", how: "手指快速抖动，用嗡鸣的颤音装饰 maqam 旋律。" }] },
"tabl-baladi": { sound: "重槌发出深沉轰鸣的“dum”，细棍发出干脆爆裂的“tak”；在户外非常响亮而穿透。", range: "无固定音高，低沉。", acoustics: "槌与细棍击打 → 两张山羊皮鼓面 → 圆柱形鼓身。", materials: "木制或金属鼓身，两张山羊皮鼓面用绳索绷紧。", making: "木制或金属鼓身，山羊皮鼓面用之字形绳索绷紧。", usage: "挂在肩上；一面用重槌击出低沉的 dum，另一面用细棍击出 tak。", role: "节奏与低音。", players: "民间鼓手，通常与 mizmar 演奏者同行。", skills: "dum 与 tak 交错的型式，如 maqsum 和 saidi。", scenes: "婚礼、mulid 节庆、游行。", repertoire: "Saʿīdī 节奏、婚礼和 zaffa 游行。", origin: "埃及与阿拉伯世界，大型双面低音鼓的民间形式。", history: "一种用重棍和细棍演奏的双面鼓，是 mizmar 在户外的搭档。", variants: "与土耳其的 davul 相关；有较小和较大的尺寸。", today: "仍在使用。", techniques: [{ name: "dum", how: "重槌击打主鼓面中心，得到深沉轰鸣的音色。" }, { name: "tak", how: "细棍击打另一面鼓面，发出尖锐的高音爆响。" }, { name: "棍滚奏", how: "细棍快速轻击，在重拍之间制造爆裂的滚奏。" }] },
"sammu": { sound: "温暖醇厚的拨弦羊肠弦音色，起音柔和，余音中等；轻柔而富于歌唱性。", range: "九根弦，可能略多于一个八度。", tuning: "巴比伦文献中记载有七种七声调弦法（išartum、kitmum、embūbum、pītum、nīd qabli、nīš gabarî、qablītum），通过依次以五度和四度重新调整一根弦在各调之间转换。", acoustics: "拨弦或扫弦 → 羊肠弦 → 木制共鸣箱。", materials: "木制共鸣箱和以横梁相连的两臂，装九根羊肠弦。", making: "木箱与两臂以横梁相连；羊肠弦缠绕在横梁上调音。", usage: "竖持或置于膝上用手指拨弦；在不同调式之间需重新调弦。", role: "为颂歌和哀歌伴奏。", players: "神庙和宫廷乐师（nāru）。", skills: "在七种命名的调弦之间以五度、四度重新调弦，并如泥板所列演奏二度双音（两根弦的音程）。", scenes: "神庙颂歌、哀歌和宫廷音乐。", repertoire: "献给诸神的颂歌；乌加里特的胡里安颂歌使用同样的调弦体系。", notation: "楔形文字的巴比伦弦号记谱，如乌加里特的胡里安歌曲（约公元前1400年）。", origin: "美索不达米亚的巴比伦人，延续苏美尔里拉琴传统。", finds: "调弦文献 CBS 10996 和 UET VII 126（古巴比伦时期，约公元前1800年）；乌尔出土的里拉琴。", history: "古巴比伦泥板（如 CBS 10996 和 UET VII 126）列出了它的九根弦，并描述如何逐步重新调弦经过七种调弦法，是已知最古老的书面音乐理论。", today: "已成历史；如今有人演奏复原乐器。", uncertain: "巴比伦术语如何对应实际音程是主要由基尔默（Kilmer）等人重构的，至今仍有争论。", techniques: [{ name: "手指拨弦", how: "手指拨单根弦，得到清晰的羊肠弦音色。" }, { name: "双音", how: "同时拨两根弦，构成巴比伦泥板中命名的某一音程。" }] },
"embubu": { sound: "带簧片味、鼻音的管声；芦苇簧管会发出嗡鸣而穿透的声音，笛式则带气息。", range: "较窄，约一个八度。", tuning: "由指孔固定；一种巴比伦里拉琴调弦法即以它命名为 embūbum。", acoustics: "气息 → 簧片（若为簧管）或边棱 → 芦苇管。", materials: "芦苇或芦秆，有时仿制为骨、银或陶。", making: "由芦苇切制；也有银、骨或陶的仿制品。", usage: "从一端吹奏，管身上开有指孔。", role: "旋律。", players: "神庙和节庆乐师。", skills: "气息控制和以指微调来弯音。", scenes: "哀歌、神庙仪式、牧人音乐和节庆。", origin: "美索不达米亚的苏美尔人和巴比伦人；一种巴比伦调弦法以它命名。", finds: "见于苏美尔和阿卡德文献；乌尔出土的银管（约公元前2500年）。", history: "长芦苇管出现在苏美尔和阿卡德文献及印章上；同一家族的管在黎凡特和迦太基世界都有演奏。", today: "已成历史。", uncertain: "embūbu 是簧管还是笛，尚不清楚。", techniques: [{ name: "指法旋律", how: "手指开合音孔，奏出带簧片味的管乐旋律线。" }, { name: "弯音", how: "半按音孔并改变气息，使音高平滑弯曲。" }] },
"zagsal": { sound: "可能是柔和的拨弦羊肠弦声，类似其他美索不达米亚的竖琴和里拉琴。", acoustics: "拨弦 → 羊肠弦 → 木制共鸣箱。", materials: "可能是装有羊肠弦的木框。", usage: "用手指拨弦，为赞美颂歌伴奏。", role: "为颂歌伴奏。", players: "神庙乐师。", skills: "拨奏和弦与琶音；具体技法不明。", scenes: "神庙赞美颂歌。", repertoire: "苏美尔颂歌，其中“zagsal”也用作赞美语。", origin: "苏美尔与巴比伦；zag-sal 一词见于苏美尔颂歌和乐器名录。", finds: "见于苏美尔颂歌和词汇表（公元前3千纪晚期至前2千纪早期）。", history: "zag-sal 究竟指哪种乐器仍有争议：可能是竖琴，也可能是里拉琴；巴比伦文献也将它用于赞美套语。", today: "已成历史。", uncertain: "该词指哪种乐器不明，因此声音与形制都是推测。", techniques: [{ name: "手指拨弦", how: "手指拨单根弦，为颂歌伴奏。" }] },
"qarnu": { sound: "粗糙嘶哑、颤抖的号声，起音粗粝；响亮传远，只有一两个音。", range: "一两个自然音。", acoustics: "唇振 → 圆锥形号管腔。", materials: "掏空的兽角，有时开有吹口。", making: "兽角切去尖端或钻出吹口，有时加热软化以定形。", usage: "在窄端以嘴唇振动吹奏。", role: "信号。", players: "牧人、守夜人、士兵和仪式官员。", skills: "为发信号而吹出一两个起音尖锐的响亮音。", scenes: "战争、狩猎信号、神庙与城邦典礼。", origin: "古代近东：苏美尔语 si 和阿卡德语 qarnu 都意为“角”。", finds: "见于苏美尔和阿卡德文献；兽角在古代近东广有描绘。", history: "牛、山羊和公羊的角自最早的时代起就在美索不达米亚、黎凡特和迦太基世界被用来发信号和行仪式。", today: "兽角至今仍有吹奏，如 shofar（羊角号）。", techniques: [{ name: "信号呼号", how: "唇在窄端振动，发出一声响亮的铜管号声。" }] },
"lilissu": { sound: "深沉轰鸣、庄严的鼓声，青铜鼓釜带来悠长的共鸣余音。", range: "无固定音高，深沉。", acoustics: "击打 → 公牛皮鼓面 → 青铜鼓釜共鸣体。", materials: "蒙以公牛皮的青铜釜形鼓身。", making: "青铜鼓釜蒙以特选黑公牛的皮，由 kalû 祭司在仪式中更换。", usage: "置于架上，用手或槌击打。", role: "仪式之声与节奏。", players: "哀歌祭司（kalû）。", skills: "为哀歌吟唱垫底的缓慢仪式鼓点。", scenes: "kalû 祭司在神庙哀歌和日月食仪式中演唱。", meaning: "为诸神所圣化；更换鼓皮的仪式要宰杀公牛并掩埋其心脏。", origin: "苏美尔与巴比伦，哀歌祭司所用的神庙鼓。", finds: "见于乌鲁克塞琉古时期的仪式泥板（公元前3世纪）；较早的印章上也有描绘。", history: "一种大型青铜釜鼓，鼓皮需通过一套涉及黑公牛的复杂仪式来更换，塞琉古时期的泥板对此有记述。", today: "已成历史。", techniques: [{ name: "仪式鼓点", how: "在大鼓面上缓慢沉重地击打，发出深沉共鸣的轰响。" }, { name: "滚奏", how: "快速交替击打，渐强为隆隆的滚奏。" }] },
"angle-harp": { sound: "明亮清脆的拨弦声，拨片起音尖锐，余音轻快短促。", range: "可能约一个半八度。", acoustics: "拨片击弦 → 羊肠弦 → 水平木制共鸣箱。", materials: "长木制共鸣箱，带竖直的弦臂和羊肠弦，常有流苏。", making: "长条水平共鸣箱配竖直弦臂；羊肠弦带垂下的流苏。", usage: "水平抱在身侧，用长拨片击弦，另一只手制音。", role: "游行中的旋律与伴奏。", players: "亚述和埃兰的宫廷乐师。", skills: "拨片横扫琴弦，配合左手制音。", scenes: "王室游行、胜利庆典和宴会。", origin: "美索不达米亚，尤其是亚述，见于尼尼微的宫殿浮雕。", finds: "尼尼微的亚述宫殿浮雕（公元前7世纪）和马达克图的埃兰乐师。", history: "一种共鸣箱水平持握、琴弦斜向上升的竖琴，用拨片击奏；见于公元前7世纪亚述和埃兰的游行中。", today: "已成历史。", techniques: [{ name: "拨片击弦", how: "长拨片扫过琴弦，奏出明亮鸣响的和弦。" }, { name: "左手制音", how: "另一只手按住不该鸣响的弦，只留下选定的音。" }] },
"vertical-harp": { sound: "清晰鸣响的拨弦音，起音柔和；弦多，各音可一同响起，形成闪烁的音浪。", range: "大型竖琴可达约两到三个八度。", acoustics: "手指拨弦 → 羊肠弦 → 直立的蒙皮共鸣箱。", materials: "蒙皮的木制共鸣箱，一根木臂，以及许多羊肠弦。", making: "直立的中空箱体蒙皮，配水平弦臂；琴弦系有流苏。", usage: "直立抱于胸前，双手手指拨弦。", role: "旋律与和声。", players: "宫廷和神庙乐师。", skills: "双手拨弦，奏和弦与旋律。", scenes: "宫廷宴会、王室狩猎和胜利宴席。", origin: "美索不达米亚和埃兰，自公元前2千纪早期起；在亚述浮雕上突出。", finds: "见于古巴比伦陶塑和亚述浮雕（如亚述巴尼拔的花园宴会，约公元前645年）。", history: "一种角形竖琴，共鸣箱直立，水平弦臂位于下方；后来传入波斯和希腊，是波斯 chang 的祖先。", variants: "后来有波斯的 chang 和希腊的 trigonon。", today: "已成历史；复原演奏者使其复活。", techniques: [{ name: "双手拨弦", how: "双手手指拨奏旋律与和弦。" }, { name: "制音", how: "用手掌按住仍在鸣响的弦，得到短而干的音。" }] },
"adapu": { sound: "干燥的中音框鼓声：中心是较深的轰响，近边缘处是清脆的拍击声。", range: "无固定音高。", acoustics: "手击 → 皮鼓面 → 浅框。", materials: "木框绷以兽皮。", making: "木框绷以兽皮。", usage: "竖持，用手击打。", role: "节奏。", players: "神庙和节庆乐师。", skills: "在中心和边缘用手击打，得到低音和高音。", scenes: "游行、神庙仪式和宫廷音乐。", origin: "美索不达米亚；adapu 见于巴比伦和亚述文献。", finds: "见于巴比伦和亚述文献；框鼓出现在公元前2千纪早期的美索不达米亚饰板上。", history: "可能是一种框鼓（有人认为是方形）；公元前2千纪早期起美索不达米亚浮雕上即有框鼓。", today: "已成历史；框鼓在该地区至今仍有演奏。", uncertain: "其确切形状（圆形还是方形）不明。", techniques: [{ name: "中心击法", how: "手掌或手指击打鼓面中央，得到深沉开放的音色。" }, { name: "边缘击法", how: "手指击打近边缘处，得到更高更尖锐的拍击声。" }] },
"bull-lyre": { sound: "可能是温暖饱满的羊肠弦音色，大共鸣箱带来深沉的共鸣；轻柔而庄严。", acoustics: "拨弦或扫弦 → 羊肠弦 → 大型木制共鸣箱。", materials: "木制共鸣箱，饰有黄金、白银和青金石的牛头以及贝壳镶嵌，木臂和横梁，羊肠弦。", making: "大型木箱，饰有黄金和青金石的牛头及贝壳镶嵌饰板，由王室工匠制作。", usage: "置于地上或膝上，站着或坐着双手拨弦。", role: "在仪式或宫廷中为歌唱伴奏。", players: "宫廷乐师，其中一些与乌尔统治者一同殉葬。", skills: "双手拨弦和制音；细节不明。", scenes: "王室宴会、神庙哀歌和丧仪。", meaning: "公牛是神圣力量的象征；琴上的嵌板描绘动物奏乐。", origin: "苏美尔，出自乌尔王陵（约公元前2500年）。", finds: "乌尔王陵（约公元前2500年），由伦纳德·伍利发掘；现藏大英博物馆和宾夕法尼亚大学博物馆。", history: "共鸣箱上饰有黄金与青金石牛头的大型里拉琴，与乌尔的贵族一同埋葬；它们的琴弦和调弦不明，但后来巴比伦里拉琴理论延续了这一传统。", today: "已成历史；“乌尔里拉琴”计划等复原乐器仍在演奏。", uncertain: "其琴弦、调弦和名称均不明。", techniques: [{ name: "拨弦", how: "手指拨长弦，得到深沉带嗡鸣的里拉琴音色。" }, { name: "制音", how: "手指按在不用的弦上使其无声。" }] },
"silver-pipes": { sound: "重构为单薄、带簧片味、穿透的双管声；实际声音不确定。", acoustics: "气息 → 可能是簧片 → 细银管。", materials: "薄银片卷成带指孔的管。", making: "银片卷成带指孔的细管。", usage: "可能呈 V 字形持握并一同吹奏，每手一管。", role: "旋律。", skills: "在成对的管上同时奏两条线；技法不明。", scenes: "乌尔的王室与神庙音乐。", origin: "苏美尔；乌尔王陵出土了一对银管（约公元前2500年）。", finds: "乌尔王陵出土的一对银管（约公元前2500年），现藏宾夕法尼亚大学博物馆。", history: "现存最古老的管乐器之一；很可能作为双管演奏，也许带簧片，但其声音只是出于猜测的重构。", today: "已成历史。", uncertain: "它们如何吹奏、听来如何，都是猜测。", techniques: [{ name: "双管演奏", how: "两管一同吹奏，一管在另一管的旋律下奏持续音。" }] },
"copper-jingles": { sound: "轻巧、干燥、叮叮作响的金属碰撞声，起音快，几乎没有延音。", range: "无固定音高，高。", acoustics: "摇动 → 金属片相互撞击。", materials: "穿在绳上的铜或早期青铜片。", making: "锤打或铸造的铜与青铜片、环，穿在绳上。", usage: "手摇或由舞者佩戴。", role: "节奏与装饰。", players: "舞者和仪式参与者；也挂在动物身上。", skills: "配合舞步闪烁的节奏性摇动。", scenes: "舞蹈、仪式和游行。", origin: "早期美索不达米亚，早于真正的铸造铃。", finds: "美索不达米亚早期遗址出土有小型铜铃片。", history: "小型的铜与青铜片、环和小粒串在一起，挂在衣服、权杖和马具上叮当作响。", today: "已成历史。", techniques: [{ name: "稳定摇动", how: "配合舞蹈或歌唱摇动，各部件撞击出干脆利落的节奏。" }, { name: "连续摇动", how: "不停地快速摇动，叮当声模糊成持续闪烁的沙沙声。" }] },
"bow-harp": { sound: "柔和温暖的拨弦声，衰减快；细腻而亲密。", acoustics: "拨弦 → 羊肠弦 → 船形共鸣箱。", materials: "木制共鸣箱和弯曲的琴颈，饰以黄金与贝壳，装羊肠弦。", making: "弯曲的木琴颈从船形箱体伸出；饰有黄金和贝壳。", usage: "竖置于膝上，双手拨弦。", role: "为歌唱伴奏。", players: "宫廷乐师。", skills: "双手拨弦；细节不明。", scenes: "乌尔的王室与神庙音乐。", origin: "苏美尔；乌尔普阿比王后墓中发现了一把弓形竖琴（约公元前2500年）。", finds: "乌尔普阿比王后墓出土的竖琴（约公元前2500年）；早期苏美尔印章上也有描绘。", history: "一种琴颈从船形共鸣箱伸出的弓形竖琴；公元前2千纪在美索不达米亚逐渐被角形竖琴取代。", today: "已成历史；弓形竖琴仍存于非洲和缅甸（saung-gauk）。", techniques: [{ name: "双手拨弦", how: "双手拨弦，得到柔和温暖的音色。" }] },
"zinar": { sound: "轻巧明亮的拨弦羊肠弦音色，安静清晰。", acoustics: "拨弦 → 羊肠弦 → 小型木制共鸣箱。", materials: "木制共鸣箱和两臂，装羊肠弦。", making: "木箱与带横梁的两臂，羊肠弦。", usage: "抱在身侧，边走边舞时拨弦或扫弦。", role: "为祭祀歌曲伴奏。", players: "赫梯都城的神庙乐师。", skills: "用拨片拨弦，另一只手制音；细节不明。", scenes: "神庙节庆和为诸神举行的游行。", origin: "赫梯统治下的安纳托利亚，其名称借自哈梯语。", finds: "见于哈图沙的赫梯节庆文献；伊南德克瓶（公元前17世纪）上有便携式里拉琴。", history: "赫梯都城哈图沙的节庆文献要求有 zinar 乐师；通常认为它就是伊南德克瓶上所绘的便携式里拉琴。", today: "已成历史。", techniques: [{ name: "拨片扫弦", how: "拨片刷过琴弦，奏出轻巧明亮的和弦。" }, { name: "拨弦", how: "拨单根弦奏旋律。" }] },
"hunzinar": { sound: "大琴架发出深沉饱满而共鸣的羊肠弦声，低音绵长鸣响。", acoustics: "拨弦（由两位乐师）→ 羊肠弦 → 立于地面的大型共鸣箱。", materials: "大型木框与共鸣箱，装羊肠弦，立于地面。", making: "带共鸣箱的高大木框，立在地上。", usage: "竖立着拨弦，有时由两位乐师分立两侧演奏。", role: "祭祀音乐中的低音与伴奏。", players: "两位神庙乐师合奏。", skills: "拨奏低音与和弦；细节不明。", scenes: "神庙仪式和祭祀节庆。", origin: "赫梯统治下的安纳托利亚，见于伊南德克瓶和许塞因代代瓶（公元前17至16世纪）。", finds: "伊南德克瓶（公元前17世纪）和许塞因代代瓶。", history: "一种巨大的立式里拉琴，在祭祀瓶上由两位乐师同时演奏；赫梯文献在小型 zinar 之外还提到一种“大”里拉琴。", today: "已成历史。", techniques: [{ name: "拨弦", how: "拨单根弦，得到深沉共鸣的音色。" }] },
"galgalturi": { sound: "若为钹，则是明亮的金属撞击声，余音鸣响。", acoustics: "撞击 → 青铜片。", materials: "可能是青铜。", usage: "两片钹随鼓点相击。", role: "节奏。", players: "神庙乐师。", skills: "节奏性的撞击和持续的鸣响。", scenes: "神庙节庆和祭祀游行。", origin: "赫梯统治下的安纳托利亚；见于节庆文献。", finds: "见于赫梯节庆文献。", history: "通常认为是一对钹，不过也有学者读作响器；它在祭祀仪式中与 arkammi 鼓同奏。", today: "已成历史。", uncertain: "它可能是钹，也可能是响器；文献没有说明。", techniques: [{ name: "撞击", how: "两片钹相击后任其鸣响。" }, { name: "闷音撞击", how: "击后把两片钹合住，发出短促干脆的撞击声。" }] },
"sawatar": { sound: "粗糙响亮的兽角号声，有一两个音。", range: "一两个自然音。", acoustics: "唇振 → 圆锥形号管。", materials: "兽角。", making: "掏空并切去尖端的兽角。", usage: "在窄端以嘴唇振动吹奏。", role: "信号与仪式。", players: "仪式官员。", skills: "一两个音的信号呼号。", scenes: "节庆、仪式和信号。", origin: "赫梯统治下的安纳托利亚；该词字面意为“角”。", finds: "见于赫梯仪式文献。", history: "赫梯仪式和节庆上吹奏的号角，以兽角制成。", today: "已成历史。", techniques: [{ name: "信号呼号", how: "唇在窄端振动，发出一声响亮的铜管号声。" }] },
"arkammi": { sound: "若为大型框鼓，则是深沉共鸣的鼓声。", range: "无固定音高。", acoustics: "击打 → 皮鼓面 → 鼓框。", materials: "木框和皮鼓面。", making: "木框配皮鼓面。", usage: "竖持，用手击打。", role: "节奏。", players: "神庙乐师。", skills: "稳定的游行鼓点。", scenes: "神庙节庆和游行。", origin: "赫梯统治下的安纳托利亚；见于节庆文献。", finds: "见于赫梯节庆文献。", history: "可能是大型框鼓；arkammi、galgalturi 和里拉琴构成文献中标准的神庙乐队。", today: "已成历史。", uncertain: "其形制是推断的；文献只给出了名称。", techniques: [{ name: "中心击法", how: "手掌或手指击打鼓面中央，得到深沉开放的音色。" }, { name: "边缘击法", how: "手指击打近边缘处，得到更高更尖锐的拍击声。" }] },
"kinnor": { sound: "甜美轻盈的拨弦羊肠弦音色，起音快、衰减柔和；轻柔得足以为一位歌者伴奏。", range: "约十根弦，可能约一个八度。", tuning: "可能按整个黎凡特通行的巴比伦–胡里安七声体系调弦。", acoustics: "拨片或手指拨弦 → 羊肠弦 → 木制共鸣箱。", materials: "木制共鸣箱和两臂，装羊肠弦。", making: "木箱和以横梁相连、长度不等的两臂；羊肠弦。", usage: "斜抱在身侧，用拨片或手指拨弦。", role: "为歌唱伴奏。", players: "利未人和歌者；在《希伯来圣经》中是大卫。", skills: "用拨片拨弦，同时另一只手压住不需要的弦。", scenes: "神庙颂歌、宴会和王室音乐。", repertoire: "《诗篇》；乌加里特的胡里安尼卡尔颂歌（h.6）。", meaning: "与喜乐和赞美相关；大卫的琴声安抚扫罗。", origin: "黎凡特：该词见于乌加里特语（knr）、腓尼基语和希伯来语。", finds: "描绘于米吉多象牙雕和印章（公元前2千纪）；巴尔·科赫巴钱币（公元132至135年）。", history: "公元前2、1千纪的不对称里拉琴，两臂常长短不一；是《希伯来圣经》中大卫王的琴，为乌加里特的胡里安歌曲等颂歌伴奏。", today: "已成历史；以色列制作有现代复原的 kinnor。", techniques: [{ name: "拨片扫弦", how: "拨片扫过琴弦，奏出明亮的和弦。" }, { name: "拨弦", how: "手指拨单根弦奏旋律。" }, { name: "制音", how: "另一只手按住不该鸣响的弦使其无声。" }] },
"halil": { sound: "带簧片味、尖锐而略带鼻音的音色，明亮传远；成对的管发出嗡鸣的双声部音响。", range: "约一个八度。", acoustics: "气息 → 簧片 → 芦苇或骨管。", materials: "芦苇、木或骨，配簧片吹口。", making: "由芦苇、木或骨切制，配簧片吹口。", usage: "作为两根管呈 V 字形持握，同时吹奏。", role: "旋律，常在持续低音之上。", players: "节庆乐师和受雇的哭丧者。", skills: "一管奏持续音，另一管奏旋律。", scenes: "节庆、游行、婚礼和哀悼。", repertoire: "节庆和朝圣音乐；哀悼（《密西拿》要求即使穷人的葬礼也须有两位 halil 乐师）。", origin: "古代黎凡特；这个希伯来词意为“穿孔的”（管）。", finds: "见于《希伯来圣经》和《密西拿》；黎凡特艺术中有双管的描绘。", history: "一种簧管，常成对使用，在整个黎凡特的节庆和哀悼中演奏；相当于希腊的阿夫洛斯管（aulos）。", today: "已成历史。", techniques: [{ name: "低音与旋律", how: "一管保持稳定的持续音，另一管吹旋律，两管同时吹奏。" }, { name: "颤音", how: "在一管上快速抖动手指，装饰旋律。" }] },
"nevel": { sound: "比 kinnor 更深沉饱满的拨弦声，琴弦鸣响更久。", acoustics: "拨弦 → 羊肠弦 → 木制或蒙皮的共鸣箱。", materials: "木头和羊肠弦；共鸣箱也许蒙皮。", usage: "用手指拨弦。", role: "为《诗篇》伴奏。", players: "圣殿的利未人乐师。", skills: "拨奏低音和和弦；细节不明。", scenes: "圣殿音乐和王室典礼。", repertoire: "《诗篇》。", origin: "古代黎凡特；《希伯来圣经》中与 kinnor 并提。", finds: "见于《希伯来圣经》和后来的犹太文献。", history: "nevel 是竖琴还是大型里拉琴仍有争议；它是比 kinnor 更大、更低沉的乐器。", today: "已成历史。", uncertain: "nevel 是竖琴还是大型里拉琴，尚无定论。", techniques: [{ name: "拨弦", how: "手指拨弦，得到温暖的竖琴音色。" }] },
"paamon": { sound: "细小明亮的叮铃声，起音轻，衰减短。", range: "无固定音高，高。", acoustics: "运动 → 铃舌撞击小铃。", materials: "青铜或黄金，带小铃舌。", making: "青铜铸造或以黄金制作。", usage: "缝在衣服上或悬挂，随运动鸣响。", role: "信号与仪式之声。", players: "缝在大祭司的长袍上。", skills: "随步行和舞蹈的节奏鸣响。", scenes: "神庙和游行。", meaning: "其声音宣告大祭司在圣所内的行动（《出埃及记》28）。", origin: "古代黎凡特。", finds: "腓尼基和迦太基遗址出土有小青铜铃；2011年在耶路撒冷圣殿山排水渠附近发现一枚金铃。", history: "《希伯来圣经》中悬挂在大祭司长袍下摆的小金铃；腓尼基和迦太基遗址也出土有类似的青铜铃。", today: "已成历史。", techniques: [{ name: "随动作鸣响", how: "佩戴者行走时铃摆动鸣响。" }, { name: "连续叮当", how: "快速运动使铃连续闪烁地鸣响。" }] },
"shofar": { sound: "粗犷尖锐的哀号般号声，带嗡鸣的边缘；通常是相距约五度的两个音，吹出长音、断音和急促的断奏。", range: "两三个自然音，相距约五度或六度。", tuning: "由号角的长度和孔径决定；不按音阶调音。", acoustics: "唇振 → 圆锥形号管腔。", materials: "公羊角，掏空并用热定形。", making: "公羊或大弯角羚的角掏空、切去尖端并钻孔，常用热使之变直或弯曲；由专门工匠制作。", usage: "在窄端以嘴唇振动吹奏。", role: "信号与仪式呼号。", players: "会堂指定的吹号人（baʿal tekiʿah）。", skills: "不同的呼号型式：长音、断音和急促断奏。", scenes: "信号、节庆和仪式。", repertoire: "新年（Rosh Hashanah）和赎罪日（Yom Kippur）结束时的 tekiʿah、shevarim 和 teruʿah 呼号。", meaning: "呼召悔改与记念；与以撒被捆绑时的公羊相关。", origin: "古代黎凡特；羊角即《希伯来圣经》中的 shofar。", finds: "《希伯来圣经》中屡有提及；古代晚期的会堂马赛克上有描绘。", history: "古代在战争和节庆中用作信号，如今仍在会堂中吹响。", variants: "短而弯曲的阿什肯纳兹公羊角，以及长而呈螺旋形的也门大弯角羚角。", today: "在世界各地的犹太仪式中仍然活跃。", techniques: [{ name: "长音（tekiah）", how: "一声长而不断的号声。" }, { name: "断音（shevarim）", how: "三声断开的哀号般号声，每声由较低音升至较高音。" }, { name: "颤音（teruah）", how: "九声或更多的急促断奏，连成颤抖的一串。" }, { name: "大长音（tekiah gedolah）", how: "非常长的结束号声，一直延长到气息用尽。" }] },
"tof": { sound: "干燥温暖的框鼓节拍：中央是深沉的咚声，边缘是明亮的拍击声；轻快，适合舞蹈。", range: "无固定音高。", acoustics: "手击 → 皮鼓面 → 浅圆框。", materials: "木框配皮鼓面。", making: "弯成的木箍，绷上皮鼓面并胶合或钉牢。", usage: "一只手竖持，另一只手用手指击打。", role: "为歌舞打节奏。", players: "主要是女性。", skills: "手指与手掌击法，中心与边缘的音色。", scenes: "女性舞蹈、凯旋歌和神庙仪式。", repertoire: "凯旋与庆祝的歌曲，如米利暗之歌。", origin: "古代黎凡特；手持框鼓的陶制女鼓手像遍见于腓尼基和迦太基遗址。", finds: "铁器时代以色列、腓尼基和迦太基出土的女性框鼓手陶俑。", history: "一种圆形框鼓，主要由女性在庆祝的歌声中演奏，从《希伯来圣经》中的米利暗之歌到迦太基神庙的陶俑皆有。", today: "已成历史；框鼓延续为 daf 和 tar。", techniques: [{ name: "中心击法", how: "手掌或手指击打鼓面中央，得到深沉开放的音色。" }, { name: "边缘击法", how: "手指击打近边缘处，得到更高更尖锐的拍击声。" }] },
"lyre": { sound: "清澈轻盈的拨弦羊肠弦音色，鸣响柔和而安静；用拨片扫弦则明亮清脆，另一只手压住不需要的弦。", range: "通常七根弦，约一个八度。", tuning: "希腊的调弦法（harmoniai），如多利亚、弗里吉亚和吕底亚，有全音阶、半音阶和微分音阶三种类型。", acoustics: "拨片或手指拨弦 → 羊肠弦 → 琴马 → 木制或龟甲共鸣箱。", materials: "木制或龟甲共鸣箱，以横梁相连的两臂，以及羊肠弦。", making: "木或龟甲制的共鸣箱蒙皮，两臂和带调弦环的横梁。", usage: "抱在身侧，右手用拨片扫弦，左手手指拨弦或制音。", role: "为歌唱伴奏。", players: "歌者、诗人和有教养的业余爱好者。", skills: "拨片扫弦配合左手制音、拨奏旋律、为不同的 harmoniai 重新调弦。", scenes: "歌唱、教育、宴会和宗教节庆。", repertoire: "抒情诗、颂歌和宴会歌曲。", origin: "东地中海与近东；七弦里拉琴出现在米诺斯克里特，后来成为希腊的 lyra。", finds: "米诺斯的哈吉亚·特里亚达石棺（约公元前1400年）；皮洛斯的迈锡尼壁画。", history: "从哈吉亚·特里亚达石棺到忒耳潘德罗斯的七弦里拉琴，再到帕尔米拉的宴会，里拉琴是整个古代世界为歌唱伴奏的核心乐器。", variants: "chelys、barbitos、phorminx 和基萨拉琴（kithara）。", today: "已成历史；如今有人演奏复原乐器。", techniques: [{ name: "拨片扫弦", how: "右手用拨片扫过琴弦，奏出明亮鸣响的和弦。" }, { name: "手指拨弦", how: "左手手指拨单根弦，得到更柔和圆润的旋律音。" }, { name: "左手制音", how: "左手手指按住不该发声的弦，使拨片扫弦后只留下选定的音在鸣响。" }] },
"triton-shell": { sound: "深沉空洞、轰鸣的号角声，边缘带气息，嘶哑而传得远。", range: "一个主音，开口处的手可使其略微变化。", acoustics: "唇振 → 贝壳的螺旋腔。", materials: "大型法螺（Charonia）贝壳。", making: "法螺壳切去或磨去尖端，做出吹口。", usage: "以嘴唇振动对着尖端切出的开口吹奏。", role: "信号与仪式呼号。", players: "祭司、水手和信号兵。", skills: "一个响亮的基音，由开口处的手来调整音色。", scenes: "神殿和海上的仪式呼号与信号。", meaning: "在希腊神话中是海神特里同的号角。", origin: "米诺斯克里特；克里特神殿中发现过法螺壳及其石制仿品。", finds: "斐斯托斯和马利亚等米诺斯神殿出土的法螺壳及石制仿品（公元前2千纪）。", history: "切去尖端的海螺，像号一样吹奏；希腊神话中是特里同的号角，整个地中海都用海螺发信号。", today: "海螺号至今在许多地方仍有吹奏。", techniques: [{ name: "吹响", how: "唇在切开的尖端振动，发出一声响亮空洞的轰鸣。" }, { name: "手遮音", how: "手放在壳口，使音色变低变暗。" }] },
"kithara": { sound: "饱满有力、明亮而共鸣的拨弦声，比里拉琴更响，拨片起音清脆，大箱体带来绵长的余音。", range: "七根弦时约一个八度或更多；后来多达十一或十二根弦。", tuning: "希腊的 harmoniai 和音阶类型；演奏会上的乐师会在各调式之间重新调弦。", acoustics: "拨片 → 羊肠弦 → 琴马 → 大木箱和中空的琴臂。", materials: "大型箱形木制共鸣箱，带中空的琴臂、装有调弦环的横梁和羊肠弦。", making: "大型箱形共鸣箱配中空琴臂，由熟练的木工制作。", usage: "用带子竖直抱在身侧；右手用拨片击弦，左手拨弦和制音。", role: "独奏，以及为歌者自己的歌声伴奏。", players: "在皮提亚竞技会和泛雅典娜竞技会上比赛的职业 kitharodes。", skills: "拨片扫弦配合左手制音、泛音，以及各 harmoniai 之间的转调。", scenes: "音乐竞赛、节庆和史诗与颂歌的演唱。", repertoire: "kitharodic nomoi；提摩修斯的《波斯人》。", notation: "希腊乐器记谱法（字母符号）。", origin: "古希腊，由荷马时代的福尔明克斯琴（phorminx）发展而来。", finds: "见于公元前6世纪起的瓶画。", history: "职业 kitharodes 在皮提亚和泛雅典娜竞技会上比赛所用的厚重演奏会里拉琴；提摩修斯等名家把弦数增加到七根以上，罗马人沿用它称为 cithara。", variants: "罗马的 cithara。", today: "已成历史。", techniques: [{ name: "拨片扫弦", how: "右手用拨片扫过琴弦，奏出明亮鸣响的和弦。" }, { name: "手指拨弦", how: "左手手指拨单根弦，得到更柔和圆润的旋律音。" }, { name: "左手制音", how: "左手手指按住不该发声的弦，使拨片扫弦后只留下选定的音在鸣响。" }, { name: "泛音", how: "拨弦时手指轻触弦的中点，得到高而如钟鸣的泛音。" }] },
"aulos": { sound: "强劲、嗡鸣、带鼻音且相当穿透的簧片声，不同于笛；两管可奏旋律配持续音或第二条线，带有粗犷而令人兴奋的棱角。", range: "每管约一个八度或略多。", tuning: "孔位固定；用套环开闭音孔以改变 harmonia；半按孔得到微分音。", acoustics: "气息 → 双芦苇簧片 → 圆柱形管腔（两管）。", materials: "芦苇、木、骨或象牙管，配青铜或银配件和芦苇双簧片。", making: "管身为芦苇、骨、象牙或木，配金属配件；簧片取自科帕伊斯湖的芦苇，由专门匠人制作。", usage: "两管同时演奏，呈 V 字形持握；演奏者常戴皮制口带（phorbeia）。", role: "旋律与持续低音。", players: "职业 auletai，常受雇演奏；会饮上也有女性阿夫洛斯管乐手。", skills: "循环换气、低音与旋律并奏、半按孔以得半音和微分音。", scenes: "戏剧合唱、祭祀、会饮、行军和竞技会。", repertoire: "悲剧、酒神颂、皮提亚 nomos、祭祀和竞技。", notation: "希腊乐器记谱法；德尔斐颂歌（公元前2世纪）。", meaning: "与狄奥尼索斯和狂喜相关；神话中雅典娜将它丢弃，玛尔绪阿斯吹奏它。", origin: "古希腊，借鉴了更古老的近东双管；罗马人称之为 tibia。", finds: "皮德纳、墨伽拉和波塞冬尼亚出土的管；卢浮宫的阿夫洛斯管；大量瓶画。", history: "一对带双簧片的管，是希腊音乐中最重要的管乐器；它为悲剧、祭祀、竞技和斯巴达行军伴奏，后来的乐手加上金属套环以涵盖更多调式。", variants: "罗马的 tibia，带弯曲喇叭口的弗里吉亚阿夫洛斯管。", today: "已成历史；如今有人演奏复原乐器。", techniques: [{ name: "低音与旋律", how: "一管保持持续音，另一管吹旋律，借 phorbeia 口带同时吹响两个簧片。" }, { name: "循环换气", how: "储存在腮中的空气使簧片不间断地发声。" }, { name: "半按孔", how: "半按音孔，使音在音阶级进之间弯成半音和微分音。" }, { name: "音孔升八度（syrinx）", how: "打开靠近簧片的小孔，使管进入高音区。" }] },
"syrinx": { sound: "柔和带气息、呜呜的笛声，每根管发一个纯净的音，起音带一口气息。", range: "每管一个音，常有七根左右，约一个八度。", tuning: "每根闭管靠长度或管内的蜡来调音。", acoustics: "气息吹过敞口 → 闭口芦苇管。", materials: "底部封闭的芦苇管，用绳和蜡捆扎。", making: "芦苇管切成渐变的长度，用绳和蜡捆扎。", usage: "抵在下唇上，吹过管口的同时左右移动。", role: "旋律。", players: "牧人。", skills: "在各管之间快速转换，以及带气息的起音。", scenes: "田园音乐、牧人之歌。", meaning: "神话中仙女绪任克斯化为芦苇，潘用它做成管。", origin: "古希腊；神话中是潘神和阿卡迪亚牧人的乐器。", finds: "见于瓶画；有罗马的实物留存。", history: "一排长度渐变的闭口芦苇管捆在一起；是一种乡野乐器，而非音乐会乐器。", variants: "外缘等长的矩形希腊形制；后来有罗马尼亚的 nai。", today: "排箫至今仍广泛演奏。", techniques: [{ name: "带气息的起音", how: "气息吹过管口，每个音以轻柔的气声开始。" }, { name: "扫管", how: "管列在唇边快速移动，奏出流畅的音阶。" }] },
"kodon": { sound: "细小明亮的铃声，起音尖锐，衰减短。", range: "无固定音高或一个高音。", acoustics: "铃舌 → 青铜铃。", materials: "带铃舌的青铜。", making: "青铜铸造。", usage: "握住手柄摇动。", role: "信号。", players: "哨兵和牧人。", skills: "稳定的鸣响脉冲。", scenes: "军中守夜、仪式和节庆。", origin: "古希腊。", finds: "希腊圣所出土的青铜铃。", history: "一种小青铜铃，哨兵夜巡、挂在牲畜身上和仪式中都会用到；该词也指号角的喇叭口。", today: "已成历史。", techniques: [{ name: "鸣响脉冲", how: "以稳定的脉冲摇动铃，发出清晰的响声。" }, { name: "连续鸣响", how: "快速摇动使铃舌不停地鸣响。" }] },
"salpinx": { sound: "响亮刺耳的号声，起音尖锐，希腊作家称之为“可怕”的声音；有几个自然音。", range: "几个自然泛音。", acoustics: "唇振 → 长直管 → 喇叭口。", materials: "长骨管或青铜管，配青铜喇叭口和号嘴。", making: "骨管或青铜管和青铜喇叭口，配号嘴。", usage: "笔直向前持握，以嘴唇振动吹奏。", role: "信号。", players: "军中号手和传令官。", skills: "在几个自然泛音上吹出响亮的信号呼号。", scenes: "战场信号、竞技会和祭祀。", repertoire: "战场信号；奥林匹亚为传令官和号手举办的比赛（自公元前396年起）。", origin: "古希腊，可能源自近东和伊特鲁里亚的号。", finds: "波士顿美术馆藏的骨与青铜制 salpinx（公元前5世纪）。", history: "一种长直青铜号，用于战争和竞技会的信号；奥林匹克运动会设有 salpinx 传令官的比赛。", today: "已成历史。", techniques: [{ name: "信号呼号", how: "唇在窄端振动，发出一声响亮的铜管号声。" }, { name: "泛音间的唇滑奏", how: "收紧嘴唇，音色不间断地跳到上一个自然泛音。" }] },
"hydraulis": { sound: "响亮明亮、管笛般的风琴音色，稳定而穿透，足以充满竞技场；快速按键则音符清脆。", range: "约一至三个八度，视音列而定。", acoustics: "泵入的空气由水压稳定 → 风箱 → 由琴键开启的唇管。", materials: "青铜管、木制键盘和风箱，以及带泵的水箱。", making: "由工程师和工匠制造：青铜管、木制键盘、水槽和气泵。", usage: "一人弹奏琴键，助手负责泵气。", role: "旋律与伴奏。", players: "职业管风琴师；据说尼禄也会演奏。", skills: "在琴键上奏持续的和弦与响亮的旋律。", scenes: "竞技场比赛、剧场、宴会和帝国典礼。", repertoire: "竞技场比赛和剧场音乐。", origin: "希腊化时期的亚历山大城，由克特西比乌斯于公元前3世纪发明。", finds: "马其顿迪翁的水压管风琴残件（公元前1世纪）；阿奎肯的管风琴（公元228年）；兹利顿马赛克。", history: "第一件键盘乐器：水压使送往排管的气流稳定；它在罗马竞技场中很流行，如兹利顿马赛克所示，是管风琴的祖先。", today: "已成历史；如今有人演奏复原乐器；管风琴是其后裔。", techniques: [{ name: "持续和弦", how: "按住琴键，水压使风保持稳定，奏出绵长如管风琴的音。" }, { name: "旋律跑动", how: "快速按键，奏出明亮如管笛的旋律。" }] },
"tympanon": { sound: "中央是深沉共鸣的拍击声，边缘是清脆的拍击声；为狂喜之舞大声演奏。", range: "无固定音高。", acoustics: "手击 → 皮鼓面 → 木箍。", materials: "木箍配皮鼓面，有时绘有彩绘。", making: "木箍配皮鼓面，有时绘有彩绘。", usage: "一只手竖持，用另一只手的手掌击打。", role: "节奏。", players: "主要是库柏勒和狄奥尼索斯崇拜中的女性。", skills: "以手掌和手指击法奏出推动的狂热节奏。", scenes: "狄奥尼索斯和库柏勒的仪式、游行与舞蹈。", origin: "古代近东，随库柏勒和狄奥尼索斯崇拜传入希腊。", finds: "见于希腊瓶画和罗马浮雕。", history: "一种圆形框鼓，主要由女性在狂喜的祭祀音乐中演奏；罗马人称之为 tympanum。", today: "已成历史；整个地中海地区至今仍演奏框鼓。", techniques: [{ name: "掌击", how: "平掌击鼓面，得到深沉轰鸣的音色。" }, { name: "指击", how: "指尖弹击边缘，得到尖锐的高音轻敲。" }, { name: "滚奏", how: "手指快速敲击，在狂喜的舞蹈中奏出隆隆的滚奏。" }] },
"barbitos": { sound: "深沉醇厚丰润的拨弦声，琴弦鸣响悠长，比里拉琴更低更暗。", range: "比龟甲里拉琴（chelys）更低。", acoustics: "拨片或手指拨弦 → 长羊肠弦 → 龟甲共鸣箱。", materials: "蒙皮的龟甲共鸣箱，长而弯曲的木臂和羊肠弦。", making: "龟甲共鸣箱配长而弯曲的木臂。", usage: "斜抱在身侧，用拨片拨弦，左手制音。", role: "为歌唱伴奏。", players: "诗人和会饮者。", skills: "拨片击弦配合左手制音，为独唱伴奏。", scenes: "会饮（雅典男子的饮酒聚会）和狄奥尼索斯场景。", repertoire: "萨福、阿尔凯奥斯和阿那克里翁的抒情诗。", origin: "爱琴海诸岛和伊奥尼亚的希腊世界，与莱斯博斯岛及诗人阿尔凯奥斯、萨福相关。", finds: "阿提卡瓶画（公元前6至5世纪）。", history: "一种琴臂长而弯曲、低音弦深沉的里拉琴；公元前6至5世纪流行于雅典，后来逐渐不用。", today: "已成历史。", techniques: [{ name: "拨片扫弦", how: "右手用拨片扫过琴弦，奏出明亮鸣响的和弦。" }, { name: "手指拨弦", how: "左手手指拨单根弦，得到更柔和圆润的旋律音。" }, { name: "左手制音", how: "左手手指按住不该发声的弦，使拨片扫弦后只留下选定的音在鸣响。" }] },
"chelys": { sound: "轻盈清晰柔和的拨弦声，衰减快；亲密而安静。", range: "七根弦，约一个八度。", tuning: "希腊的 harmoniai，如多利亚、弗里吉亚和吕底亚。", acoustics: "拨片或手指拨弦 → 羊肠弦 → 琴马 → 蒙皮的龟甲。", materials: "蒙以牛皮的龟甲作共鸣箱，角或木制的琴臂，以及七根羊肠弦。", making: "龟甲蒙以牛皮，配角制或木制琴臂和装有调弦环的横梁。", usage: "倾斜抱在身侧，用拨片击弦，左手手指拨弦。", role: "为歌唱伴奏。", players: "学童、业余爱好者和诗人。", skills: "拨片扫弦、手指拨弦和制音；在不同 harmoniai 中调弦。", scenes: "学校教育、会饮和家庭歌唱。", repertoire: "抒情诗和宴会歌曲。", meaning: "在《荷马颂歌·致赫耳墨斯》中，婴儿神用龟甲发明了它。", origin: "古希腊；神话中赫耳墨斯神用龟甲做了第一把。", finds: "希腊墓葬和圣所中留存有龟甲共鸣箱；大量瓶画。", history: "希腊日常使用的里拉琴，雅典男孩在学校学习；它比演奏会用的基萨拉琴更轻巧简单。", today: "已成历史；如今有人演奏复原乐器。", techniques: [{ name: "拨片扫弦", how: "右手用拨片扫过琴弦，奏出明亮鸣响的和弦。" }, { name: "手指拨弦", how: "左手手指拨单根弦，得到更柔和圆润的旋律音。" }, { name: "左手制音", how: "左手手指按住不该发声的弦，使拨片扫弦后只留下选定的音在鸣响。" }] },
"cymbala": { sound: "明亮尖锐的金属撞击声或叮叮鸣响，衰减快而闪烁。", range: "无固定音高或大致音高，高。", acoustics: "撞击 → 杯形青铜片。", materials: "青铜杯，常以绳相连。", making: "铸造并锤打的青铜杯，常以绳相连。", usage: "每手持一片，相互敲击。", role: "节奏。", players: "库柏勒和狄奥尼索斯崇拜中的舞者。", skills: "为舞蹈奏出尖锐的撞击和节奏型式。", scenes: "狂喜的祭祀仪式、舞蹈和游行。", origin: "古代近东，随库柏勒和狄奥尼索斯进入希腊祭祀音乐。", finds: "希腊和罗马遗址出土的青铜钹；见于瓶画和浮雕。", history: "舞者撞击的小型杯形青铜钹；罗马人在同样的祭祀中使用。", today: "已成历史；指钹延续为 zil 和 sagat。", techniques: [{ name: "撞击", how: "两片小钹相击，明亮地鸣响。" }, { name: "闷音咔嗒", how: "击后把钹片合住，发出短促干脆的咔嗒声。" }] },
"phorminx": { sound: "柔和温暖的拨弦羊肠弦声，简朴而共鸣，为吟诵的声音伴奏。", range: "可能有三到五根弦，音域较窄。", acoustics: "拨弦 → 羊肠弦 → 圆底木制共鸣箱。", materials: "木制共鸣箱和琴臂，装羊肠弦。", making: "圆底的木制共鸣箱和琴臂。", usage: "抱在身侧，拨弦或用拨片击弦。", role: "为史诗吟唱伴奏。", players: "史诗吟游诗人（aoidoi），如《奥德赛》中的德摩多科斯。", skills: "以简单的拨弦型式为歌唱的史诗伴奏。", scenes: "史诗吟唱、宴席和宗教颂歌。", repertoire: "史诗歌唱。", origin: "早期希腊；荷马史诗中吟游诗人的里拉琴。", finds: "几何纹时期和早期古风时期的瓶画（公元前8至7世纪）。", history: "一种圆底共鸣箱的里拉琴，供史诗歌者使用；后来发展成更大的演奏会基萨拉琴。", today: "已成历史。", techniques: [{ name: "拨片击弦", how: "拨片扫过寥寥几根弦，为吟唱的史诗断句。" }, { name: "拨弦", how: "拨单根弦，奏简单的旋律。" }] },
"keras": { sound: "粗糙低沉的响亮号角声，有几个音。", range: "几个自然音。", acoustics: "唇振 → 弯曲的圆锥形号角。", materials: "兽角或青铜。", making: "兽角，或仿其形状的青铜号。", usage: "以嘴唇振动吹奏。", role: "信号。", players: "士兵。", skills: "几个音的响亮信号呼号。", scenes: "军队信号和狩猎。", origin: "古希腊和马其顿；该词意为“角”。", finds: "见于希腊文献。", history: "兽角，或仿其形状的弯曲青铜号，在军事信号中与 salpinx 并用。", today: "已成历史。", techniques: [{ name: "信号呼号", how: "唇在窄端振动，发出一声响亮的铜管号声。" }] },
"cornu": { sound: "深沉有力、带铜管味且略粗糙的号声，比 tuba 更响更暗；有几个自然音。", range: "低音区的数个自然泛音。", acoustics: "唇振 → 盘成 G 形的长圆锥形青铜管 → 喇叭口。", materials: "带喇叭口和木横杆的长青铜管。", making: "青铜片锤打焊接成长管，弯成弧形，并用木横杆加固。", usage: "扛在肩上，喇叭口高过头顶，握着横杆持号。", role: "信号与典礼音乐。", players: "军团号手（cornicines）和竞技会的乐手。", skills: "在自然泛音上吹出信号呼号。", scenes: "军团信号、角斗竞技和葬礼。", repertoire: "军事信号和竞技场音乐。", origin: "意大利的伊特鲁里亚人和罗马人。", finds: "庞贝出土的两支 cornu（公元79年）；兹利顿马赛克上 cornu 与水压管风琴同时出现。", history: "一种围绕吹奏者的大型 G 形青铜号，用木横杆支撑；它为罗马军团提供信号，也在竞技会上与水压管风琴同奏。", today: "已成历史；现有复原品。", techniques: [{ name: "信号呼号", how: "唇在窄端振动，发出一声响亮的铜管号声。" }, { name: "泛音间的唇滑奏", how: "收紧嘴唇，音色不间断地跳到上一个自然泛音。" }] },
"tuba-roman": { sound: "响亮明亮、刺耳的直号声，起音强劲；罗马作家称之为可怕的声音。", range: "几个自然音。", acoustics: "唇振 → 长直青铜管 → 圆锥形喇叭口。", materials: "带圆锥形喇叭口和可拆卸号嘴的长青铜管。", making: "带可拆卸号嘴的长直青铜管。", usage: "笔直向前持握，以嘴唇振动吹奏。", role: "信号。", players: "军中号手（tubicines）和仪式号手。", skills: "在几个泛音上吹出威严的信号呼号。", scenes: "战斗、祭祀、竞技会和葬礼。", repertoire: "进攻和撤退的信号；净化号角的 Tubilustrium 节。", origin: "意大利的伊特鲁里亚人和罗马人。", finds: "罗马军事遗址出土的残件；图拉真柱上有描绘。", history: "一种长直青铜号；为军团吹响进攻和撤退，也为祭祀和竞技会开场（并非现代的大号 tuba）。", today: "已成历史。", techniques: [{ name: "信号呼号", how: "唇在窄端振动，发出一声响亮的铜管号声。" }, { name: "泛音间的唇滑奏", how: "收紧嘴唇，音色不间断地跳到上一个自然泛音。" }] },
"lituus": { sound: "明亮穿透的号声，上翘的喇叭口带来鼻音般的边缘。", range: "几个自然音。", acoustics: "唇振 → 长直管 → J 形喇叭口。", materials: "青铜管和喇叭口。", making: "青铜管和上翘的喇叭口。", usage: "像号一样向前持握，以嘴唇振动吹奏。", role: "信号与仪式。", players: "骑兵号手和祭司。", skills: "在自然泛音上吹出信号呼号。", scenes: "骑兵信号、宗教仪式和葬礼。", meaning: "得名于占卜官（augur）的弯曲手杖。", origin: "意大利的伊特鲁里亚人和罗马人。", finds: "伊特鲁里亚和罗马的实例，如采雷（Caere）出土的 lituus。", history: "一种长直青铜管，带 J 形上翘的喇叭口，得名于占卜官的弯曲手杖；用于骑兵和仪式。", today: "已成历史。", techniques: [{ name: "信号呼号", how: "唇在窄端振动，发出一声响亮的铜管号声。" }, { name: "泛音间的唇滑奏", how: "收紧嘴唇，音色不间断地跳到上一个自然泛音。" }] },
"buccina": { sound: "粗糙如号角的呼声，比 tuba 更柔和更低。", range: "几个自然音。", acoustics: "唇振 → 弯曲的号角。", materials: "兽角或青铜。", making: "兽角或青铜。", usage: "以嘴唇振动吹奏。", role: "信号。", players: "罗马营地的信号兵（buccinatores）。", skills: "短促的信号呼号。", scenes: "营地守夜、集会和信号。", origin: "意大利的罗马人。", finds: "见于罗马文献；形制存在争议。", history: "一种弯曲的号角，起初是兽角，后来用青铜，用于在罗马营地标示夜间的更次；确切形状存在争议。", today: "已成历史。", uncertain: "它是一种号角，还是 cornu 的变体，存在争议。", techniques: [{ name: "信号呼号", how: "唇在窄端振动，发出一声响亮的铜管号声。" }] },
"tintinnabulum": { sound: "一串小铃欢快的叮当声，明亮而高，随风或被触碰而响。", range: "数个高音铃声。", acoustics: "运动 → 铃舌撞击小青铜铃。", materials: "青铜铃，铃舌系在链上。", making: "铸造的青铜铃，用链子挂在青铜小像上，小像常带诙谐或阳具形象。", usage: "悬挂起来，让风或动作使其鸣响。", role: "仪式与护佑之声。", skills: "自由鸣响；用于音乐时，按节奏摇动。", scenes: "门口、花园、游行和仪式。", meaning: "人们相信它能驱赶恶灵和恶眼。", origin: "意大利的罗马人。", finds: "庞贝和赫库兰尼姆出土的大量青铜 tintinnabula（公元1世纪）。", history: "一串小青铜铃，挂在小像或框架上，人们相信它能辟邪，挂在门口和花园里。", today: "已成历史；风铃延续了这一理念。", techniques: [{ name: "自由鸣响", how: "挂在风中，铃不规则地发出轻柔的叮当声。" }, { name: "按节奏摇动", how: "在手中快速摇动，铃不停地叮当作响。" }] },
"tlapitzalli": { sound: "清澈甜美、略带气息的哨笛音色；陶土赋予它柔和圆润的色泽和明亮的高音区。", range: "四个孔约一个八度，上方还有超吹音。", tuning: "由孔位决定；音阶因笛而异，没有统一标准。", acoustics: "气息 → 风道 → 边棱 → 带喇叭口的陶管。", materials: "烧制的陶土，有时用芦苇或骨，开有四个指孔。", making: "由陶工模制烧成，喇叭口常做成花形。", usage: "像竖笛一样通过风道吹口吹奏，向前平举。", role: "旋律。", players: "祭司、青年男子和舞者。", skills: "超吹、花舌和仿鸟鸣的装饰音。", scenes: "神庙节庆、舞蹈和游行。", meaning: "在托什卡特尔节（Toxcatl）上，扮演特斯卡特利波卡的人在献祭前于神庙台阶上折断他的笛子。", origin: "墨西卡人（阿兹特克人）和墨西哥中部的其他民族；这个纳瓦特尔语词意为“被吹的东西”。", finds: "大神庙（Templo Mayor）等阿兹特克遗址出土的大量陶笛。", history: "一种烧制的陶制风道笛，末端常做成花形喇叭口；被选为扮演神特斯卡特利波卡的青年在献祭前于神庙台阶上折断他的笛子。", today: "复兴音乐人仍复制其历史形制。", techniques: [{ name: "吐音旋律", how: "舌头通过风道开始每个音，吐音清晰如哨。" }, { name: "超吹", how: "吹得更用力，音色跳到上方的高音区，尖锐明亮。" }, { name: "花舌", how: "吹奏时卷动舌头，得到嗡嗡如鸟鸣的音色。" }] },
"teponaztli": { sound: "温暖空洞的木质敲击声，音高清晰；两个舌片发出两个音，常相距四度、五度或三度，衰减短而圆润。", range: "两个音高。", tuning: "由两个舌片的大小和厚度决定。", acoustics: "橡胶头鼓槌击打 → 两个木舌 → 空心原木。", materials: "硬木原木，从下方掏空，配橡胶头鼓槌。", making: "硬木原木从下方掏空，并在上面刻出 H 形的缝；常雕成动物或人形。", usage: "水平放在架子上，用橡胶头鼓槌击打两个舌片。", role: "节奏与双音旋律型式。", players: "神庙乐师和舞蹈乐师。", skills: "双音型式与滚奏，与 huehuetl 交错配合。", scenes: "神庙仪式、cuicacalli（歌舞之家）的舞蹈和战争。", repertoire: "舞曲；阿兹特克歌词集（Cantares Mexicanos）中有为它记录的鼓音节。", notation: "《墨西哥歌集》中“toco, tiqui, titi”之类的鼓音节。", meaning: "被视为神圣，有时被当作活物对待。", origin: "墨西卡人和墨西哥中部的其他纳瓦人，以及整个中美洲。", finds: "1519年以前的雕刻 teponaztli 有留存，如国家人类学博物馆所藏。", history: "一根掏空的原木，顶部刻出 H 形的缝，形成两个发出不同音高的舌片；1519年以前的动物造型雕刻实物有留存。", variants: "有大小不同的尺寸；雕成美洲豹等形态。", today: "在纳瓦人社群和复兴者中演奏。", techniques: [{ name: "双音击法", how: "橡胶头鼓槌击打两个舌片，各发出自己的木质音高。" }, { name: "滚奏", how: "在一个舌片上快速交替击打，产生滚动的空洞隆隆声。" }] },
"death-whistle": { sound: "刺耳、呼啸、如尖叫的噪声，像风或人的尖叫，没有明确音高；非常响亮。", range: "噪声，带粗糙的高频带。", acoustics: "气息 → 腔体内的湍流 → 噪声。", materials: "烧制的陶土，内有产生气流湍动的腔体。", making: "模制烧成的陶土，做成头骨形。", usage: "用力吹过短风道，发出尖啸般的呼啸声。", role: "仪式之声。", skills: "改变气压，使尖叫从嘶嘶声变成嚎叫。", scenes: "仪式和典礼；如今用于声音演示和电影。", origin: "阿兹特克统治下的墨西哥中部；特拉特洛尔科的埃赫卡特尔神庙出土了头骨形陶哨。", finds: "特拉特洛尔科埃赫卡特尔神庙的头骨形哨，1999年发现于一座墓葬中。", history: "它如今的名字是考古学家起的绰号；其仪式作用不明，尽管有人将它与风神埃赫卡特尔和死者联系起来。", today: "复制品很受欢迎。", uncertain: "其原名和仪式用途不明。", techniques: [{ name: "尖啸", how: "用力吹过短风道，发出尖啸般的呼啸嚎叫。" }, { name: "气压渐变", how: "改变气压，使声音从嘶嘶声变为尖叫。" }] },
"tetzilacatl": { sound: "明亮的金属锣鸣，起音清晰，衰减中等。", range: "每片一个音高。", acoustics: "击打 → 悬挂的铜片。", materials: "锤打的铜。", making: "锤打的铜片，运用墨西哥西部的冶金技术制成。", usage: "悬挂起来，用槌击打。", role: "仪式之声。", players: "神庙乐师。", skills: "单次共鸣的击打，标示仪式时刻。", scenes: "神庙仪式和典礼。", origin: "墨西哥中部的墨西卡人，使用墨西哥西部的铜冶金技术。", finds: "殖民时期有关阿兹特克仪式的文献中提到过。", history: "一种悬挂的铜片，如锣般敲击，殖民时期有关阿兹特克仪式的文献中有提及。", today: "已成历史。", techniques: [{ name: "单击", how: "用槌击打悬挂的铜片，得到悠长共鸣的鸣响。" }, { name: "闷击", how: "击后用手按住铜片，发出短促的金属撞击声。" }] },
"atecocolli": { sound: "深沉轰鸣、嘶哑的号角声，丰满而穿透，传得很远。", range: "一个主音，可被手略微弯曲。", acoustics: "唇振 → 螺旋形贝壳腔。", materials: "凤凰螺（Strombus）或类似的海螺壳，有时带雕刻装饰。", making: "切去尖端的大海螺，有时配有号嘴和雕刻装饰。", usage: "在切开的尖端以嘴唇振动吹奏。", role: "信号与仪式呼号。", players: "祭司和战士。", skills: "深沉的吼声，由开口处的手来调整音色。", scenes: "神庙信号、战争和节庆；今天仍在舞蹈中吹响。", meaning: "与水、海洋和羽蛇神（克查尔科亚特尔）相关。", origin: "中美洲的墨西卡人及其之前的许多民族；海螺号自奥尔梅克时代起就有发现。", finds: "奥尔梅克、特奥蒂瓦坎和阿兹特克遗址出土的海螺号。", history: "切去尖端的大型海螺，用来宣告仪式、在神庙标示时辰以及战争中发信号。", today: "仍在墨西卡复兴舞蹈（danza de los concheros）中吹响。", techniques: [{ name: "吼声", how: "唇在切开的尖端振动，发出深沉空洞的呼声。" }, { name: "手遮音", how: "手放在开口处，使音色弯曲变暗。" }] },
"huehuetl": { sound: "深沉共鸣、轰鸣的鼓声，余音悠长；演奏者通过击打靠近中心或边缘来改变音高。", range: "无固定音高，低沉；有两个音（中心和边缘）。", acoustics: "手击 → 美洲豹皮或鹿皮 → 高大的空心原木。", materials: "掏空的原木，常雕有人物，鼓面为美洲豹皮或鹿皮。", making: "掏空的原木，雕出三条腿，常雕有人物；鼓面蒙皮。", usage: "直立放置，用手击打，中心与边缘各发出一个音高。", role: "节奏与低音。", players: "神庙和舞蹈乐师。", skills: "在中心与边缘用手击打，为舞者奏出滚动的节奏型式。", scenes: "舞蹈、神庙节庆和战争；今天仍是墨西卡舞蹈团体的核心。", repertoire: "阿兹特克舞曲和典礼。", meaning: "神圣；雕刻的 huehuetl 描绘战士和神祇。", origin: "墨西卡人和墨西哥中部的其他民族。", finds: "马利纳尔科的 huehuetl（约1500年）和滕安戈的 huehuetl。", history: "一种立在三条雕刻腿上的高圆筒鼓，直立演奏；huehuetl 与 teponaztli 构成阿兹特克舞蹈音乐的核心一对。", variants: "有几种尺寸。", today: "在墨西卡舞蹈（danza Azteca/conchero）团体中演奏。", techniques: [{ name: "中心击法（低）", how: "手掌或手指击打鼓面中央，得到深沉开放的音色。" }, { name: "边缘击法（高）", how: "手指击打近边缘处，得到更高更尖锐的拍击声。" }, { name: "滚奏", how: "双手快速交替，为舞者奏出滚动的节拍。" }] },
"ocarina": { sound: "纯净、圆润、空洞、近乎正弦波的哨音，起音柔和，几乎没有气息噪声；多腔的陶笛可同时发出两个音。", range: "通常不到一个八度；不能超吹。", tuning: "音高取决于有多少孔开着，而非开哪个孔；音阶因件而异。", acoustics: "气息 → 风道 → 边棱 → 球形陶腔（亥姆霍兹共鸣器）。", materials: "烧制的陶土，常有彩绘。", making: "模制烧成的陶土，常做成鸟、兽或人形。", usage: "通过风道吹奏；音高取决于开着多少孔。", role: "旋律与仪式之声。", players: "仪式专家和普通人；常放入墓中。", skills: "叉指和气息控制来调音高，以及颤音。", scenes: "仪式、葬礼和节庆；也是儿童玩具。", origin: "中美洲和安第斯北部，玛雅、穆伊斯卡等许多民族制作陶制容器笛。", finds: "贾伊纳岛的玛雅人形哨（古典期，公元600至900年）；中美洲和哥伦比亚的大量容器笛。", history: "球形陶笛常做成动物或人形，已制作了数千年；贾伊纳岛的玛雅人形哨尤为著名。", variants: "单腔、双腔和多腔；一孔或多孔的哨。", today: "由陶工为游客和复兴者制作；现代欧洲的 ocarina 是19世纪另行发展的乐器。", techniques: [{ name: "指法旋律", how: "打开音孔使音高升高，得到纯净圆润的音色。" }, { name: "颤音", how: "手指在孔上抖动，奏出快速的颤动音。" }] },
"whistle-pot": { sound: "柔和、颤动、带气息的哨音，有时像鸟鸣，由壶内水的流动而发出。", range: "一两个音。", acoustics: "水的移动或气息 → 空气被推过哨口 → 壶腔。", materials: "烧制的陶土，内有哨。", making: "由陶工制作的两个或多个相连陶壶，带哨口。", usage: "倾斜壶身使其中的水流动，或从壶嘴吹气。", role: "仪式之声。", skills: "轻轻倾斜以维持柔和带气息的音色。", scenes: "仪式和祭献。", origin: "中美洲和安第斯，包括玛雅人在内的许多民族均有制作。", finds: "莫奇卡、奇穆等安第斯文化的鸣壶；中美洲的实例。", history: "相连的陶壶，其中流动的水把空气推过哨口，因此倾斜壶身或向其中吹气时便会发声。", today: "由陶工和研究者复制。", techniques: [{ name: "水驱哨音", how: "倾斜壶身使水流动，把空气推过哨口，发出柔和带气息的音色。" }, { name: "吹哨", how: "向壶嘴吹气，得到更强而稳定的哨音。" }] },
"xul": { sound: "单薄、明亮、高亢、略带气息的哨音，能穿透鼓声；装饰音听来像快速的颤音。", range: "加上超吹约一个半八度。", acoustics: "气息 → 风道 → 边棱 → 竹管。", materials: "竹或木，带风道吹口和几个指孔。", making: "由演奏者自己用竹或芦苇切制。", usage: "向前平举，通过风道吹奏。", role: "旋律。", players: "玛雅高地城镇的男子。", skills: "高音区带装饰的旋律、颤音和超吹音。", scenes: "舞剧、cofradía（宗教兄弟会）游行和节庆。", repertoire: "《拉比纳尔·阿奇》（Rabinal Achí）和《鹿舞》（Baile del Venado）等舞剧。", origin: "危地马拉和墨西哥的玛雅人；xul 是基切语中“笛”的说法。", finds: "古典玛雅遗址出土的骨笛和陶笛；博南帕克壁画中的笛。", history: "竹、骨或陶制的小型风道笛自古典期起便有演奏；如今 xul 在高地城镇为舞剧和鼓伴奏。", today: "在危地马拉高地仍然活跃。", techniques: [{ name: "吐音旋律", how: "舌头通过风道开始每个音，吐音清晰如哨。" }, { name: "颤音", how: "手指在孔上快速抖动，在相邻两个音高之间交替。" }, { name: "超吹", how: "吹得更用力，音色跳到上方的高音区，尖锐明亮。" }] },
"copper-bell": { sound: "干燥的叮当震响声，起音快，衰减短。", range: "无固定音高，高。", acoustics: "摇动 → 松动的铃丸撞击闭合的铃壁。", materials: "铸造的铜或铜金合金，带铃丸。", making: "以失蜡法用铜或铜金合金铸造。", usage: "佩戴在身上，或串在一起摇动。", role: "节奏与装饰。", players: "舞者和贵族。", skills: "随舞步节奏地叮当作响。", scenes: "舞蹈、祭献和游行。", meaning: "也被用作贵重的贸易品和祭品。", origin: "约公元800年后的中美洲，源于墨西哥西部的铜加工；许多被献入奇琴伊察的圣井。", finds: "奇琴伊察圣井中祭献的数百枚铃；约公元800年后墨西哥西部的铃。", history: "内含松动铃丸的闭合式小铸铃（crotal）被广泛交易，由舞者和贵族佩戴。", today: "历史形制；crotal 铃至今仍由舞者佩戴。", techniques: [{ name: "叮当作响", how: "配合舞蹈或歌唱摇动，各部件撞击出干脆利落的节奏。" }, { name: "连续摇动", how: "不停地快速摇动，叮当声模糊成持续闪烁的沙沙声。" }] },
"hom": { sound: "深沉粗糙、空洞的号声，基音强，更偏木质而非铜管味。", range: "一两个自然音。", acoustics: "唇振 → 长直木管或葫芦管。", materials: "木、树皮或葫芦节，有时带葫芦喇叭口。", making: "掏空的木头或接起来的葫芦。", usage: "向前持握，以嘴唇振动吹奏，常成对使用。", role: "信号与典礼。", players: "典礼乐师。", skills: "持续的低音和在几个泛音上吹出的呼号。", scenes: "王室游行、战争，以及《拉比纳尔·阿奇》等舞剧。", repertoire: "游行；《拉比纳尔·阿奇》（Xajoj Tun）。", origin: "玛雅人；博南帕克壁画（约公元790年）中绘有长号。", finds: "博南帕克壁画（约公元790年）。", history: "木制或葫芦制的长直号在游行中吹响；长号至今仍在《拉比纳尔·阿奇》（Xajoj Tun）舞剧中鸣响。", today: "长号保存于《拉比纳尔·阿奇》中。", techniques: [{ name: "持续音", how: "嘴唇稳定地振动，发出持续的低音。" }, { name: "泛音间的唇滑奏", how: "收紧嘴唇，音色不间断地跳到上一个自然泛音。" }] },
"pax": { sound: "深沉共鸣的手鼓声，中央轰鸣，边缘更尖锐。", range: "无固定音高，低沉。", acoustics: "手击 → 皮鼓面 → 高大的木鼓身。", materials: "掏空的原木，鼓面为鹿皮或美洲豹皮。", making: "掏空的原木，蒙皮鼓面。", usage: "直立放置，用手击打。", role: "节奏。", players: "典礼鼓手。", skills: "在中心与边缘用手击打，稳定的游行鼓点。", scenes: "王室游行、舞蹈和仪式。", origin: "尤卡坦的玛雅人；尤卡坦玛雅语名称 pax 见于殖民时期词典。", finds: "博南帕克壁画；见于殖民时期尤卡坦玛雅语词典。", history: "一种用手演奏的高大立鼓，是阿兹特克 huehuetl 在玛雅的对应物；博南帕克壁画中它与龟甲鼓一起出现。", today: "名称为历史名；立鼓至今仍在玛雅典礼中演奏。", techniques: [{ name: "中心击法", how: "手掌或手指击打鼓面中央，得到深沉开放的音色。" }, { name: "边缘击法", how: "手指击打近边缘处，得到更高更尖锐的拍击声。" }] },
"tunkul": { sound: "温暖空洞的木质敲击声，有两个清晰的音高；深沉共鸣的节拍，衰减短。", range: "两个音高。", acoustics: "槌击 → 两个木舌 → 空心原木。", materials: "掏空的硬木原木，配橡胶头槌。", making: "硬木原木掏空并开缝，形成两个舌片。", usage: "侧放，用槌击打舌片。", role: "节奏。", players: "典礼乐师。", skills: "双音型式与滚奏。", scenes: "仪式、舞蹈和《拉比纳尔·阿奇》。", repertoire: "《拉比纳尔·阿奇》舞剧。", origin: "玛雅人；tunk'ul 是尤卡坦玛雅语的名称，tun 是基切语的名称。", finds: "见于殖民时期的玛雅文献。", history: "一种带两个舌片、发出两个音高的空心原木木鼓，类似阿兹特克的 teponaztli；tun 至今仍在危地马拉的《拉比纳尔·阿奇》舞剧中鸣响。", today: "仍活跃于《拉比纳尔·阿奇》，该剧于2008年被联合国教科文组织列入名录（2005年宣布）。", techniques: [{ name: "双音击法", how: "槌击两个舌片，发出两个木质音高。" }, { name: "滚奏", how: "快速交替击槌，得到滚动的隆隆声。" }] },
"marimba": { sound: "温暖醇厚的木质音色，起音柔和，共鸣管上的薄膜带来嗡嗡的鸣响；滚奏（反复击打）使音变成持续颤动的声音。", range: "马林巴 doble：大型乐器约六个半八度。", tuning: "较早的马林巴为全音阶；marimba doble 为平均律的全半音阶。", acoustics: "槌击 → 木音条 → 带嗡鸣薄膜的管状或箱形共鸣器（charleo）。", materials: "hormigo 木音条架在葫芦或木箱共鸣器之上，每个共鸣器带一片会嗡鸣的小薄膜。", making: "hormigo 木音条通过雕刻调音；共鸣器为木制，薄膜用猪肠；由马林巴制作世家制造。", usage: "数位演奏者沿乐器站立，用橡胶头槌击打音条。", role: "一件乐器兼具旋律、和声与低音。", players: "三四人围着一件乐器，常为家庭合奏。", skills: "redoble 震音滚奏，高音、中音和低音演奏者的交错声部。", scenes: "每个城镇的节庆、cofradía 庆典、婚礼和舞蹈。", repertoire: "危地马拉的 sones；《谢拉胡的月亮》（Luna de Xelajú）；《高地铁路》（Ferrocarril de los Altos）。", meaning: "高地玛雅人与拉迪诺人节庆的象征。", origin: "危地马拉和墨西哥南部，殖民时期非洲和原住民传统在此交汇；确切起源存在争议。", history: "较早的全音阶 marimba de tecomates 带有嗡鸣薄膜的葫芦共鸣器；约1894年克萨尔特南戈制造了全半音阶的 marimba doble，马林巴成为玛雅高地及其邻近民族最钟爱的乐器。", variants: "marimba de tecomates（葫芦）、marimba sencilla、marimba doble（grande 和 tenor）。", today: "仍活跃；是高地节庆的日常之声，在家中、教堂和广场上演奏。", uncertain: "其起源于非洲还是原住民，仍有争议。", techniques: [{ name: "单击", how: "橡胶槌击一块音条，得到短促温暖、带薄膜嗡鸣的音。" }, { name: "震音滚奏（redoble）", how: "在同一块音条上快速交替击槌，使音持续成闪烁的滚奏。" }] },
"chirimia": { sound: "响亮、带鼻音、明亮而带簧片味的唢呐音色，略粗糙而颤动，适合户外游行。", range: "约一个半八度。", tuning: "指孔固定；本地调弦与欧洲全音阶有所不同。", acoustics: "气息 → 双簧片 → 圆锥形木制管腔。", materials: "木制圆锥形管身，配棕榈叶或竹制双簧片。", making: "由本地工匠用木头车制或雕刻；簧片用棕榈叶或竹。", usage: "簧片整个含入口中，用力吹奏。", role: "旋律。", players: "原住民城镇乐师（chirimiteros），常为 cofradía 服务。", skills: "循环换气，在鼓声之上奏带装饰的旋律。", scenes: "cofradía 游行、圣徒节和舞剧。", repertoire: "游行、圣徒节和舞剧的 sones。", origin: "16世纪西班牙双簧管传入中美洲，被玛雅及其他原住民城镇采用。", history: "传教士为教会音乐而传授，chirimía 成为本地乐器，在游行中与鼓同奏；玛雅乐师用它保存自己的 sones。", variants: "墨西哥、危地马拉和哥伦比亚各地有不同的尺寸。", today: "在玛雅及其他原住民城镇仍然活跃。", techniques: [{ name: "循环换气", how: "储存在腮中的空气使带簧片味的音色不间断。" }, { name: "颤音装饰", how: "手指快速抖动，装饰旋律。" }] },
"tambor": { sound: "干燥清脆、爆裂的鼓声，带些许沙沙声；较深的击打发出柔和的轰鸣。", range: "无固定音高。", acoustics: "槌击 → 两张绳索绷紧的皮鼓面 → 木鼓身。", materials: "木鼓身，鹿皮或山羊皮鼓面，绳索绷紧。", making: "木鼓身，两张皮鼓面以绳索绷紧。", usage: "挂在肩上，用一根或两根鼓槌击打。", role: "节奏。", players: "与 chirimía 乐手搭档的城镇乐师。", skills: "稳定的游行鼓点，以及在 chirimía 之下的滚奏。", scenes: "cofradía 游行、圣徒节和舞剧。", repertoire: "游行和舞剧。", origin: "西班牙的军用和游行用鼓，在殖民时期被玛雅城镇采用。", history: "一种双面绳索绷紧的鼓，与 chirimía 一起成为 cofradía 游行和舞剧的标准搭档。", today: "仍在使用。", techniques: [{ name: "槌击", how: "鼓槌击打鼓面，得到清脆利落的节拍。" }, { name: "滚奏", how: "双槌快速交替，得到持续的滚奏。" }, { name: "击边", how: "鼓槌击打木鼓身或边缘，发出干脆的咔嗒声。" }] },
"quena": { sound: "温暖、带气息、萦绕心头的笛声，低音区丰满，高音区明亮尖锐；可以起音强劲，并带富有表现力的揉音。", range: "G 调盖那笛约 G4 至 E6，两个半八度。", tuning: "前面六个孔和一个拇指孔；现代 G 调盖那笛为全音阶，也可通过叉指奏出半音；较古老的使用本地音阶，常为五声音阶。", acoustics: "气息 → 气流冲击缺口 → 敞口竹管。", materials: "竹（或木、骨，如今也有 PVC），带 U 形缺口、六个前孔和一个拇指孔。", making: "竹、骨、木或 PVC，由本地工匠制作。", usage: "竖持，演奏者对着顶端边缘的缺口吹气。", role: "旋律。", players: "克丘亚和艾马拉乐师；现代民间合奏团。", skills: "气息揉音、滑音、颤音，以及 yaraví 哀歌中富有表现力的超吹高音区。", scenes: "节庆、哀歌、求爱和现代安第斯乐队。", repertoire: "huayno、yaraví；《老鹰之歌》（El cóndor pasa）。", origin: "安第斯，克丘亚人、艾马拉人和更早的民族；骨制和陶制缺口笛早在印加之前就有发现。", finds: "秘鲁前印加遗址出土的骨制和陶制缺口笛。", history: "一种缺口式的端吹笛，遍及印加疆域；20世纪成为世界各地民间合奏团中安第斯音乐的标志。", variants: "quena、quenacho（较低）、mama quena。", today: "仍活跃，演奏广泛。", techniques: [{ name: "缺口吹奏旋律", how: "气息在缺口处被劈开，得到带气息、萦绕心头的音色。" }, { name: "气息揉音", how: "脉冲式的气息使音波动。" }, { name: "滑音", how: "手指从孔上滑开，使音弯曲。" }, { name: "颤音", how: "手指快速抖动，装饰旋律。" }, { name: "超吹音区", how: "加强气息，把音抬到 yaraví 哀歌中尖锐的高八度。" }] },
"siku": { sound: "带气息、空灵、空洞的音色，起音带强烈的“嗤”声；多人以交错方式吹奏时会脉动搏动，深沉的 toyo 则厚重多风。", range: "每半边六至七根管；合起来超过一个八度；tropas 合奏覆盖数个八度。", tuning: "管按长度调音；ira 和 arka 交替分担音符；合奏时以平行的八度、五度和四度吹奏。", acoustics: "气息吹过敞口管顶 → 闭口竹管。", materials: "底部封闭的竹管，捆成一排或两排。", making: "竹管切割、调音，用线捆扎。", usage: "竖持抵在下唇上，吹过管口。", role: "交错分担的旋律。", players: "社群团体中的艾马拉和克丘亚男子。", skills: "交错（hocket，两半相扣）、带重音的气息起音，以及 tropas 中平行的八度和五度。", scenes: "节庆、社群游行和舞蹈团。", repertoire: "节庆用的 sikuri 音乐（普诺的 sikuris）。", origin: "的的喀喀湖周围的安第斯，艾马拉和克丘亚人，其根源远早于印加。", history: "两半（ira 和 arka）各持交替的音符，因此两人以交错方式共奏一条旋律；大型团体（tropas）演奏多种八度尺寸的 siku，最大的是 toyo。", variants: "toyo、sanka、malta、chuli 各种尺寸。", today: "仍活跃；普诺地区的 sikuri 音乐受到秘鲁的认定。", techniques: [{ name: "交错奏（hocket）", how: "两人共用一个音阶，每排各奏隔一个的音，交错成一条旋律。" }, { name: "重音气息起音", how: "尖锐带气息的一口气使每个音以“嗤”声开始。" }, { name: "颤动气息", how: "脉动颤抖的气息使音色搏动。" }] },
"antara": { sound: "带气息、空灵的笛声，起音带强烈的“嗤”声；陶制的更柔和圆润。", range: "通常约一个八度。", tuning: "管按长度调音；音阶各异。", acoustics: "气息吹过敞口管顶 → 闭口竹管或陶管。", materials: "竹，古代实物则为烧制的陶土。", making: "竹管排成一列捆扎，或模制陶土。", usage: "抵在下唇上，吹奏时左右移动。", role: "旋律。", players: "安第斯乐师。", skills: "在管列上快速跑动，以及颤动的气息重音。", scenes: "仪式、节庆和牧人音乐。", origin: "安第斯中部；纳斯卡等印加之前的民族制作过陶制和竹制的 antara。", finds: "纳斯卡人（约公元前100年至公元600年）已调音的陶制 antara。", history: "一种由一人演奏的单排排箫，不同于成对演奏的 siku；纳斯卡的陶工在一千五百多年前就制作了调好音的陶制 antara。", today: "仍活跃于秘鲁音乐中。", techniques: [{ name: "吹音", how: "气息吹过管口，得到纯净带气息的音色。" }, { name: "扫过管列", how: "管列快速掠过嘴唇，奏出一串扫过的音阶。" }, { name: "颤动气息", how: "颤动的气息形成搏动的重音。" }] },
"pinkillu": { sound: "尖锐、明亮、略带气息的哨音，常成群演奏，声音稠密而重叠。", range: "约一个半八度。", acoustics: "气息 → 风道 → 边棱 → 木管或竹管。", materials: "竹或木，带塞块风道吹口和几个指孔。", making: "木或竹，由本地工匠制作。", usage: "竖持，通过风道吹奏。", role: "旋律。", players: "雨季中的男子。", skills: "尖锐的超吹旋律和颤音，常以平行的群体演奏。", scenes: "狂欢节和雨季的农事节庆。", meaning: "与降雨和作物生长相关。", origin: "安第斯，克丘亚和艾马拉社群。", history: "一种在作物生长的雨季演奏的风道笛，与旱季的排箫相对；各村的尺寸各不相同。", variants: "各村有多种尺寸。", today: "仍活跃。", techniques: [{ name: "吐音旋律", how: "舌头通过风道开始每个音，吐音清晰如哨。" }, { name: "超吹", how: "吹得更用力，音色跳到上方的高音区，尖锐明亮。" }, { name: "颤音", how: "手指在孔上快速抖动，在相邻两个音高之间交替。" }] },
"chilchil": { sound: "明亮高亢的叮当声，随每一步响起，短促清脆。", range: "无固定音高，高。", acoustics: "运动 → 小金属铃。", materials: "铜、青铜或银。", making: "小型铸造或锤制的铃。", usage: "佩戴在腿上或衣服上，或用手摇动。", role: "节奏。", players: "舞者。", skills: "随舞步节奏地叮当作响。", scenes: "舞蹈和节庆。", origin: "安第斯；克丘亚语中指小金属铃。", finds: "印加及更早遗址出土的小金属铃。", history: "印加时代舞者和牲畜都佩戴铜、青铜或银制的小铃；同类的铃串今天仍由舞者佩戴。", today: "仍活跃。", techniques: [{ name: "叮当作响", how: "配合舞蹈或歌唱摇动，各部件撞击出干脆利落的节奏。" }, { name: "连续摇动", how: "不停地快速摇动，叮当声模糊成持续闪烁的沙沙声。" }] },
"pututu": { sound: "深沉嘶哑、轰鸣的号角声，嗡鸣强劲而传得远。", range: "一个主音。", acoustics: "唇振 → 螺旋形贝壳腔。", materials: "太平洋沿岸的凤凰螺（Strombus），高地社群则用牛角。", making: "切去尖端的凤凰螺或类似的海螺。", usage: "以嘴唇振动吹过尖端的孔。", role: "信号。", players: "社群权威（varayoq）和节庆乐手。", skills: "深沉传远的呼声，由开口处的手塑形。", scenes: "典礼、集会、印加时代的战争和今天的节庆。", origin: "安第斯；海螺号早在印加之前就已吹响，如查文德万塔尔（约公元前900年）的装饰海螺所示。", finds: "查文德万塔尔出土的装饰凤凰螺号（约公元前900年）。", history: "在印加疆域中，它用来召集社群，也在战争中吹响；如今由社群权威在节庆中吹奏。", today: "在安第斯社群中仍活跃。", techniques: [{ name: "呼号", how: "唇在尖端振动，发出深沉传远的呼声。" }, { name: "手遮音", how: "手放在开口处，使音色弯曲变暗。" }] },
"wankar": { sound: "深沉轰鸣的鼓声，槌击带干脆的起音。", range: "无固定音高，低沉。", acoustics: "槌击 → 皮鼓面 → 木制或空心鼓身。", materials: "木或竹箍鼓身，美洲驼皮或山羊皮鼓面。", making: "木鼓身配皮鼓面。", usage: "挂在肩上或手持，用槌击打。", role: "节奏。", players: "节庆中的男子；女性演奏较小的 tinya。", skills: "稳定的脉动，为 siku 和 pinkillu 合奏定调。", scenes: "节庆、收获和游行。", origin: "安第斯；克丘亚语 wankar 指一种鼓。", finds: "西班牙编年史家对库斯科的记述。", history: "编年史家描述了印加各种尺寸的鼓，包括在库斯科节庆上演奏的大鼓；小型 tinya 鼓由女性演奏。", today: "安第斯的鼓仍然活跃。", techniques: [{ name: "槌击", how: "鼓槌击打鼓面，得到深沉稳定的节拍。" }, { name: "击边", how: "鼓槌击打木边，发出干脆的咔嗒声。" }] },
"charango": { sound: "明亮、闪烁、叮当作响的音色，来自十根双弦，清脆高亢，衰减快；快速扫弦（rasgueo）产生闪烁的震音。", range: "约 E4 至 A5 及以上，大致两个八度，处于明亮的音区。", tuning: "G4–C5–E5–A4–E5（回环定弦），五组双弦，中间的 E 组为八度。", acoustics: "拨弦或扫弦 → 尼龙或羊肠弦 → 小木琴身。", materials: "雕刻的木制（旧时为犰狳壳）琴身，短琴颈，五组尼龙或金属双弦。", making: "由安第斯制琴师用整块木头雕成（旧时用犰狳壳）。", usage: "抱在胸前扫弦或拨弦。", role: "和声、节奏与旋律。", players: "安第斯男子；现代民间合奏团。", skills: "rasgueo 扫弦、快速震音，以及跨组弦的 campanella（钟声般）拨弹。", scenes: "huayno 舞蹈、求爱歌曲、节庆和安第斯乐队。", repertoire: "huayno、cueca、yaraví、狂欢节音乐。", origin: "今日玻利维亚和秘鲁一带的安第斯，殖民时期由西班牙吉他和维胡埃拉琴（vihuela）演变而来。", history: "一种十弦的小型鲁特琴，被安第斯乐师据为己有；有的曾用犰狳壳制作，如今多用雕刻的木头。", variants: "walaycho（较小）、charangón（较大）、ronroco。", today: "仍活跃，演奏广泛。", techniques: [{ name: "扫弦（rasgueo）", how: "手指掠过所有弦组，奏出明亮有节奏的扫弦。" }, { name: "震音（trémolo）", how: "在一组弦上快速交替拨弹，使音持续闪烁。" }, { name: "钟声拨弹（campanella）", how: "旋律音分布在不同的弦组上，使每个音都叠在下一个音之上如钟声般鸣响。" }] },
"arpa-andina": { sound: "明亮鸣响的拨弦声，大箱体带来深沉共鸣的低音；低音既拨又敲。", range: "约四个八度。", tuning: "全音阶，通常按大调定弦。", acoustics: "拨弦 → 尼龙或羊肠弦 → 大型船形木制共鸣箱。", materials: "木框和大共鸣箱，装尼龙或羊肠弦，全音阶定弦。", making: "由本地工匠制作，带船形木箱。", usage: "坐着演奏，竖琴靠在肩上；另一位演奏者（golpeador）可像敲鼓一样敲打共鸣箱。", role: "低音与和声；也奏旋律。", players: "安第斯民间乐师，城乡皆有。", skills: "左手奏低音线条，右手奏旋律跑动，以及在箱体上的 golpe 打击。", scenes: "huayno 与 yaraví、节庆、婚礼和游行。", repertoire: "huayno、yaraví、剪刀舞（danza de tijeras）。", origin: "安第斯，源于16世纪传教士带来的西班牙全音阶竖琴。", history: "安第斯的制琴师造出了带大型船形共鸣箱的竖琴；它为 huayno 和缓慢的 yaraví 伴奏，游行时倒挂在肩上演奏。", variants: "阿亚库乔竖琴、库斯科竖琴。", today: "仍活跃。", techniques: [{ name: "拨弦", how: "右手拨旋律，左手奏低音线条。" }, { name: "敲箱（golpe）", how: "另一位演奏者用手像敲鼓一样敲打共鸣箱。" }, { name: "制音", how: "用手掌按住仍在鸣响的低音弦，得到短而干的音。" }] },
"waqra-phuku": { sound: "粗犷、带铜管味、有力的号声，边缘明亮；长音在自然音之间滑动。", range: "数个自然音。", acoustics: "唇振 → 相接牛角的螺旋。", materials: "接在一起的牛角节，有时带金属箍。", making: "牛角片接成螺旋形，用蜡和布封住。", usage: "在窄端以嘴唇振动吹奏。", role: "信号与节庆音乐。", players: "克丘亚社群的男子。", skills: "在自然泛音上吹呼号，宽广明亮的泛音。", scenes: "烙印牲畜的节庆（圣地亚哥节）、村庄节庆。", repertoire: "曼塔罗河谷的节庆音乐；herranza（牲畜标记）。", origin: "秘鲁安第斯中部，西班牙人带来牛之后克丘亚社群的乐器。", history: "把牛角片拼接成一支长长的螺旋号；曼塔罗河谷和库斯科周边仍有演奏。", today: "仍活跃。", techniques: [{ name: "信号呼号", how: "唇在窄端振动，发出一声响亮的铜管号声。" }, { name: "泛音间的唇滑奏", how: "收紧嘴唇，音色不间断地跳到上一个自然泛音。" }] },
"bombo": { sound: "深沉轰鸣、沉闷的鼓点，边缘的槌击起音硬；非常响亮。", range: "无固定音高，低沉。", acoustics: "槌击 → 两张皮鼓面 → 木鼓身。", materials: "掏空的原木或弯曲木片制成的鼓身，山羊皮或美洲驼皮鼓面，绳索绑缚。", making: "掏空的原木或弯木鼓身，蒙山羊皮或绵羊皮，用绳索绷紧。", usage: "挂在肩上或手持，用带垫的槌击鼓面，用细棍击边缘。", role: "节奏与低音。", players: "安第斯乐师。", skills: "huayno 的长短短型式，边缘与鼓面交替击打。", scenes: "huayno 舞蹈、节庆和安第斯民间乐队。", repertoire: "huayno 舞曲、恰卡雷拉（chacarera）。", origin: "安第斯，源于西班牙军鼓和本地鼓传统的克里奥尔鼓。", history: "一种绳索绷紧的大型双面鼓，为 huayno 和安第斯乐队保持节拍。", variants: "阿根廷的 bombo legüero。", today: "仍活跃。", techniques: [{ name: "击面", how: "带垫的鼓槌击打鼓面，发出深沉的轰鸣。" }, { name: "击边", how: "细棍击打木边，发出干脆的咔嗒声。" }] },
"native-flute": { sound: "柔和温暖、带气息的空洞音色，起音轻柔，略带嗡声；揉音和装饰音赋予它哀婉如人声的感觉。", range: "约一个八度多一点。", tuning: "通常是五声小调音阶；较古老的笛各有各的定音。", acoustics: "气息 → 慢气室 → 由塞块引导的风道 → 边棱 → 管腔。", materials: "雪松或其他木材，配用皮带绑住的雕刻塞块。", making: "用雪松或其他木头雕成，塞块常雕成鸟形；由笛匠制作。", usage: "向前平举，轻轻从端部吹气。", role: "独奏旋律。", players: "年轻男子，传统上用于求爱。", skills: "气息揉音、装饰音、半按孔和富有表现力的滑音。", scenes: "求爱、独自冥想的演奏、典礼。", repertoire: "情歌；R. 卡洛斯·中井（R. Carlos Nakai）的《峡谷三部曲》（Canyon Trilogy）。", meaning: "求爱与个人的表达。", origin: "北美平原和林地的民族，包括拉科塔人（Lakota）。", history: "一种双腔笛，外部的塞块（常雕成鸟形）把气流引向音孔；传统上是年轻男子的求爱乐器，20世纪后期被广泛复兴。", today: "20世纪后期以来被广泛复兴。", techniques: [{ name: "气息揉音", how: "脉动的气息使柔和带气息的音波动。" }, { name: "装饰音", how: "手指快速抬起，在主音之前弹出一个短音。" }, { name: "滑音", how: "手指慢慢从孔上滚开，使音高滑行。" }, { name: "半按孔", how: "半按音孔，得到音阶级进之间的音。" }] },
"turtle-rattle": { sound: "干燥清脆、急促的沙沙声，带木质空洞的质感。", range: "无固定音高。", acoustics: "摇动或敲击 → 龟壳内的种子或小石子。", materials: "装有种子或小石子的鳄龟壳，配木柄。", making: "鳄龟的壳以龟颈作柄，里面装樱桃核或石子。", usage: "握住龟颈，敲击在长凳上或摇动。", role: "节奏。", players: "长屋中的歌者。", skills: "随歌者打出节奏性的敲击。", scenes: "羽毛舞等长屋典礼。", repertoire: "大羽毛舞及其他典礼。", meaning: "乌龟在豪德诺索尼人（Haudenosaunee）的创世故事中居于核心。", origin: "五大湖东部的豪德诺索尼人（易洛魁人）。", history: "用鳄龟壳制成，以龟颈作柄，为大羽毛舞及长屋的其他典礼伴奏。", today: "仍活跃。", techniques: [{ name: "击长凳", how: "把摇铃往长凳上敲，发出尖锐的咔嗒节拍。" }, { name: "摇动", how: "在手中摇动，发出干燥的沙沙声。" }] },
"water-drum": { sound: "共鸣鸣响、略带音高的鼓点，起音明亮；湿润的皮面会“歌唱”。", range: "无固定音高或大致音高；由水位调节。", acoustics: "槌击 → 湿皮 → 盛水的小桶。", materials: "小木桶或掏空的原木，内装水，鼓面为鞣制的皮。", making: "盛有水的小桶，蒙以鞣制的皮。", usage: "一只手持握，用雕刻的小槌击打。", role: "节奏，引领社交舞蹈。", players: "领唱者。", skills: "通过弄湿皮面和晃动水来调音，为歌者打出快速稳定的节拍。", scenes: "长屋中的社交舞蹈、典礼。", repertoire: "社交舞蹈和典礼。", origin: "豪德诺索尼人和东部林地的其他民族。", history: "一只装了部分水、蒙以湿皮的小木桶；水使它发出鸣响、可调的声音，并引领社交舞蹈。", today: "仍活跃。", techniques: [{ name: "槌击", how: "雕刻的小槌击打湿润的鼓面，得到明亮鸣响的节拍。" }] },
"horn-rattle": { sound: "清脆明亮、轻巧的沙沙声，起音干燥而断奏。", range: "无固定音高。", acoustics: "摇动 → 角内的铅砂或种子。", materials: "牛角、木塞和手柄，种子或铅砂。", making: "用木柄塞住的牛角。", usage: "歌者随水鼓的节奏摇动。", role: "节奏。", players: "社交舞蹈中的歌者。", skills: "稳定的摇动，并以尖锐的重音标示歌曲的段落。", scenes: "社交舞蹈和典礼。", origin: "豪德诺索尼人，在能获得牛角之后出现；它延续了更古老的树皮和葫芦摇铃。", history: "用木柄塞住、内装铅砂或种子的牛角；歌者在社交舞蹈中用它打拍子。", today: "仍活跃。", techniques: [{ name: "稳定摇动", how: "配合舞蹈或歌唱摇动，各部件撞击出干脆利落的节奏。" }, { name: "连续摇动", how: "不停地快速摇动，叮当声模糊成持续闪烁的沙沙声。" }] },
"whistle": { sound: "尖锐、高亢、带气息的哨音。", range: "一个或少数几个音。", acoustics: "气息 → 边棱 → 管。", materials: "木、竹或骨。", making: "木或骨。", usage: "急促地吹响，常为短促的呼声。", role: "信号与典礼。", skills: "配合舞蹈的短促尖锐爆发音。", scenes: "典礼和舞蹈。", origin: "北美东部林地的民族。", history: "简单的木制或骨制哨在北美各民族中广泛使用，用于典礼和发信号。", today: "仍活跃。", techniques: [{ name: "短促吹响", how: "一口急促的气息吹出尖锐的爆发音。" }, { name: "颤音", how: "快速的气息脉冲吹出颤动的哨音。" }] },
"eagle-bone": { sound: "穿透的、高亢尖锐的哨音；众多舞者一起吹时，形成闪烁如鸟鸣的合唱。", range: "一个高音。", acoustics: "气息 → 边棱 → 骨管。", materials: "鹰翅骨，有时配羽毛或串珠。", making: "开有音孔的鹰翅骨。", usage: "含在口中，舞蹈时急促地吹响。", role: "祈祷与典礼。", players: "太阳舞的舞者。", skills: "随鼓点反复吹出尖锐的哨声。", scenes: "太阳舞（wiwáŋyang wačhípi）及其他典礼。", meaning: "向造物主神圣的祈祷；鹰是信使。", origin: "平原民族，包括拉科塔人（Lakota）。", history: "用鹰翅骨制成的哨，太阳舞中舞者吹响它作为祈祷。", today: "仍活跃于典礼之中。", techniques: [{ name: "尖锐吹响", how: "急促的气息吹出穿透的哨声，随鼓点反复。" }] },
"hoof-rattle": { sound: "柔和、干燥、哗啦作响的沙沙声。", range: "无固定音高。", acoustics: "运动 → 蹄或悬蹄相互撞击。", materials: "穿在皮绳上的鹿悬蹄或鹿蹄，常系在木棍上。", making: "鹿的悬蹄或蹄。", usage: "手摇，或由舞者佩戴在腿上和腰带上。", role: "节奏。", players: "舞者。", skills: "配合鼓点和舞步打拍子。", scenes: "典礼和舞蹈。", origin: "平原及更远处的民族。", history: "鹿的悬蹄或蹄挂在木棍上或佩戴在身上，每走一步便沙沙作响。", today: "仍活跃。", techniques: [{ name: "稳定摇动", how: "配合舞蹈或歌唱摇动，各部件撞击出干脆利落的节奏。" }, { name: "连续摇动", how: "不停地快速摇动，叮当声模糊成持续闪烁的沙沙声。" }] },
"big-drum": { sound: "深沉轰鸣、稳定的脉动，起音圆润；众多鼓手齐击如同一颗心跳。", range: "无固定音高，低沉。", acoustics: "带垫的鼓槌击打 → 生皮鼓面 → 木框。", materials: "木框配生皮鼓面，用带垫的鼓槌演奏。", making: "带生皮鼓面的大鼓，常是重新蒙皮的现代低音鼓。", usage: "放在架上；数位歌者围坐，边唱边一同击打。", role: "节奏与脉动。", players: "由歌者组成的鼓队。", skills: "齐击的节拍、带重音的荣誉拍，以及跟随领唱者改变速度。", scenes: "powwow（波瓦聚会）、典礼和舞蹈。", repertoire: "powwow 歌曲：草舞、部族间舞蹈（intertribal）。", meaning: "鼓声是整个族群的心跳。", origin: "平原民族，包括拉科塔人（Lakota）。", history: "一种平放的大型双面鼓，由一圈歌者同时演奏；成为 powwow 鼓队的核心。", today: "仍活跃。", techniques: [{ name: "齐击", how: "数位歌者一同击鼓，得到深沉稳定的脉动。" }, { name: "荣誉拍", how: "比平稳节拍更响的强重音，标示歌曲中的特别时刻。" }] },
"banjo": { sound: "明亮、带弹拨感、打击性强而鸣响的拨弦声，衰减快；鼓皮赋予它利落有力的起音。", range: "五弦：约 D3 至 D6，三个八度。", tuning: "五弦班卓琴为开放 G 调（gDGBD）；另有许多其他定弦。", acoustics: "拨弦 → 钢弦 → 琴马 → 绷在圆框上的薄膜。", materials: "圆形木制或金属框，皮（如今为塑料）鼓面，长琴颈和五根弦，其中一根为短的持续音弦。", making: "木框、皮或塑料鼓面、带短第五弦的琴颈；由制琴师制作。", usage: "横置于身前，用手指或向下拨弦、或指弹演奏。", role: "节奏与旋律。", players: "最初是黑人音乐家；后来有阿巴拉契亚、蓝草和爵士的演奏者。", skills: "clawhammer（frailing）向下拨弦、落拇指（drop-thumb）和三指斯克拉格斯滚奏。", scenes: "老式舞会、弦乐队、蓝草音乐和门廊音乐。", repertoire: "老式音乐（old-time）、蓝草（厄尔·斯克拉格斯）、早期爵士。", origin: "加勒比和北美被奴役的非洲人，源于西非的葫芦鲁特琴，如 akonting。", history: "最初是黑人音乐家的葫芦乐器，19世纪经由吟游歌舞秀（minstrel show）传开，加上了第五根短持续音弦和木框，成为阿巴拉契亚老式音乐和蓝草的核心。", variants: "次中音班卓琴、拨片班卓琴、葫芦班卓琴。", today: "仍活跃。", techniques: [{ name: "clawhammer（爪锤式）", how: "指甲背面向下击弦，拇指勾第五弦，形成推进感的“嘣-嗒嗒”节奏。" }, { name: "斯克拉格斯滚奏", how: "拇指与两指以滚动型式拨弹，奏出快速倾泻而下的音符。" }, { name: "滑音", how: "左手手指沿品丝滑动，滑入音中。" }, { name: "泛音", how: "手指在第12品上方轻触琴弦，得到钟鸣般的声音。" }, { name: "扫弦", how: "手掠过所有琴弦，奏出明亮的和弦。" }] },
"cornet": { sound: "醇厚温暖、圆润的铜管音色，比小号更柔和更暗，快速跑动灵活，缓慢的曲调则抒情。", range: "降 B 调短号记谱 F♯3–C6（实际音低一个全音），约两个半八度。", tuning: "降 B 调，三个活塞键奏出平均律的半音阶。", acoustics: "唇振 → 杯形号嘴 → 圆锥形铜管与活塞键 → 喇叭口。", materials: "铜管，三个活塞键和圆锥形管腔。", making: "用铜管工厂制造，带活塞键。", usage: "向前持握，右手手指按键，以嘴唇振动吹奏。", role: "主旋律。", players: "城镇乐队和铜管乐队的乐手。", skills: "活塞键技巧、双吐音和三吐音、抒情独奏。", scenes: "城镇铜管乐队、游行、野餐和南北战争的团队。", repertoire: "进行曲（苏萨）、短号独奏曲，如《威尼斯狂欢节》。", origin: "1820年代的法国，在邮政号上加装活塞键。", history: "廉价、醇厚而灵活，带活塞键的短号是19世纪美国每个城镇的铜管乐队的主角，后来才被小号取代。", variants: "降 B 调和降 E 调高音短号；牧羊人拐杖形。", today: "仍活跃，尤其在英式铜管乐队中。", techniques: [{ name: "连奏旋律", how: "靠活塞键和平稳的气息，得到温暖抒情的音色。" }, { name: "双吐音", how: "交替发“tu-ku”音节，奏出快速重复的音。" }, { name: "花舌", how: "卷动舌头，得到低吼般嗡鸣的音色。" }] },
"pump-organ": { sound: "柔和、带簧片味、持续、略带鼻音的音色，轻轻起伏；拉栓可使音色从笛音变为明亮。", range: "约五个八度（F1–F6）。", tuning: "平均律；簧片固定。", acoustics: "脚踏风箱 → 吸入的风 → 簧室中的自由簧片。", materials: "木柜，配黄铜自由簧片、风箱、拉栓和脚踏板。", making: "由工厂制造（Estey、Mason & Hamlin），木制琴壳、风箱和黄铜簧片。", usage: "演奏者在弹键盘时用脚踩踏板送风。", role: "和声与伴奏。", players: "教会管风琴师和家庭乐手。", skills: "稳定的踩踏、拉栓选择，以及持续的圣诗和弦。", scenes: "客厅、乡村教会、圣诗歌唱和歌唱学校。", repertoire: "圣诗和客厅歌曲。", origin: "19世纪中叶的欧洲和美国，源于自由簧片的实验。", history: "Estey 和 Mason & Hamlin 等美国厂商售出数十万台客厅风琴；在钢琴变得买得起之前，它是乡村教会和家庭的键盘乐器。", variants: "美式吸风簧风琴、欧式压风 harmonium。", today: "多已成历史，由收藏者保存。", techniques: [{ name: "持续和弦", how: "稳定的踩踏使簧片持续有风，奏出绵长的圣诗和弦。" }, { name: "颤音拉栓", how: "拉栓使风脉动，音色因而搏动。" }] },
"rope-bass-drum": { sound: "深沉轰鸣、略显粗糙的沉闷声，衰减长。", range: "无固定音高，低沉。", acoustics: "槌击 → 两张小牛皮鼓面 → 木鼓身。", materials: "木鼓身、小牛皮鼓面、木箍和绳索。", making: "木鼓身，用绳索和皮耳（leather ears）绷紧。", usage: "用背带挂着，用带垫的鼓槌击打。", role: "节奏与脉动。", players: "笛鼓队（fife-and-drum corps）和城镇乐队的鼓手。", skills: "稳定的行进鼓点，以及在横笛之下的重音。", scenes: "游行、民兵集结、南北战争的团队和城镇乐队。", repertoire: "笛鼓进行曲。", origin: "欧洲军乐队，18世纪起被美国民兵和鼓队采用。", history: "一种深沉的木鼓，鼓面由绳索和皮耳绷紧；为笛鼓队和城镇乐队保持节拍。", today: "仍活跃于笛鼓队和历史重演中。", techniques: [{ name: "行进鼓点", how: "带垫的鼓槌击打鼓面，发出深沉稳定的轰鸣。" }, { name: "闷音", how: "手按在鼓面上制音，发出短促的闷响。" }] },
"bugle": { sound: "明亮清晰的铜管呼号，音色饱满；只有自然泛音，因此呼号听来开阔而大胆。", range: "五六个自然泛音，约一个半八度。", tuning: "固定的自然泛音列。", acoustics: "唇振 → 圆锥形铜管 → 喇叭口。", materials: "绕一圈的铜或黄铜管，圆锥形管腔。", making: "用黄铜工厂制造。", usage: "以嘴唇振动吹奏；音高只靠唇的松紧改变。", role: "信号。", players: "军队号手和侦察兵。", skills: "泛音之间的唇滑奏，清晰地吐出呼号。", scenes: "骑兵和军队的号令、葬礼（Taps）、鼓队。", repertoire: "《熄灯号》（Taps）、《起床号》（Reveille）、《开饭号》（Mess Call）。", origin: "18世纪的欧洲，源于狩猎号。", history: "一种无活塞键、仅限自然泛音的铜号；军队用它发营地和战斗号令，美国骑兵的军号曲如《熄灯号》广为人知。", today: "仍活跃于军事典礼中。", techniques: [{ name: "吐音呼号", how: "呼号的每个音都用舌头清晰地开始。" }, { name: "唇滑奏", how: "不吐音，靠唇的松紧在泛音之间滑动。" }] },
"valve-trumpet": { sound: "明亮辉煌、有力的铜管音色，起音尖锐；马里亚奇乐手用宽阔的揉音并以三度演奏。", range: "约 F♯3–C6（记谱）。", tuning: "降 B 调，平均律，三个活塞键。", acoustics: "唇振 → 带活塞键的圆柱形管 → 喇叭口。", materials: "铜管，三个活塞键和喇叭口。", making: "用黄铜工厂制造。", usage: "水平持握，右手按键，以嘴唇振动吹奏。", role: "主旋律。", players: "马里亚奇小号手。", skills: "明亮的揉音、抖音、唇颤音，以及与第二支小号的平行三度。", scenes: "马里亚奇小夜曲、节庆、婚礼和 charreada（牛仔竞技）。", repertoire: "马里亚奇的 sones 和 rancheras：《黑女人之歌》（El Son de la Negra）、《亲爱的天空》（Cielito Lindo）。", origin: "欧洲，19世纪初在自然小号上加装了活塞键。", history: "1930至40年代，小号通过广播和电影加入哈利斯科的马里亚奇，两支小号奏平行三度成为经典音响的一部分。", today: "仍活跃；马里亚奇列入联合国教科文组织非物质文化遗产名录（2011年）。", techniques: [{ name: "明亮揉音", how: "嘴唇或手的快速脉动使音闪烁，是马里亚奇的风格。" }, { name: "抖音", how: "嘴唇在两个泛音之间快速翻转，形成宽阔的颤音。" }, { name: "滑奏", how: "半按活塞键并配合嘴唇，在音之间滑动。" }] },
"guitarron": { sound: "深沉圆润、有冲击力的低音，起音强，以八度演奏，声音宏大轰鸣。", range: "约 A1–A3（实际音高）。", tuning: "定弦为 A1–D2–G2–C3–E3–A2。", acoustics: "拨弦（每次两根弦）→ 尼龙或羊肠弦 → 大型凸背琴身。", materials: "大型木制琴身，V 形琴背，短而无品的琴颈和六根弦。", making: "由墨西哥制琴师制作，琴身深，琴背凸起。", usage: "抱在身侧，同时拨两根弦奏八度。", role: "低音。", players: "马里亚奇低音手。", skills: "八度拨弦、低音跑动，以及 son jalisciense 中的切分型式。", scenes: "马里亚奇小夜曲和节庆。", repertoire: "马里亚奇音乐。", origin: "墨西哥西部，哈利斯科及邻近各州的乐师之间。", history: "一种琴身极大而深、琴背凸起的六弦低音吉他，源自西班牙的低音吉他；它为马里亚奇奏出低音线条。", today: "仍活跃。", techniques: [{ name: "八度拨弦", how: "同时拨两根弦奏八度，得到深沉有冲击力的低音。" }, { name: "闷音", how: "拨弦后立刻用手掌按住琴弦，得到短促的重击音。" }] },
"arpa-grande": { sound: "深沉共鸣、轰鸣的拨弦声，低音弦也会敲击共鸣箱作打击音。", range: "约四个八度。", tuning: "全音阶。", acoustics: "拨弦 → 琴弦 → 大型木制共鸣箱。", materials: "木框和大共鸣箱，装尼龙弦，全音阶定弦。", making: "由米却肯和哈利斯科的本地工匠制作。", usage: "站着或坐着演奏；也可敲击箱体作打击。", role: "低音与和声。", players: "Tierra Caliente（热地）的竖琴手。", skills: "低音线条和快速的旋律跑动，敲击共鸣箱。", scenes: "老式马里亚奇、节庆和 son abajeño。", repertoire: "Tierra Caliente 的 sones 和 gustos。", origin: "墨西哥西部（哈利斯科和米却肯），源于殖民时期传教会的西班牙竖琴。", history: "大型全音阶竖琴是早期马里亚奇的核心乐器，至今仍是 Tierra Caliente 的 arpa grande 合奏团（conjuntos de arpa grande）的主角。", today: "仍活跃。", techniques: [{ name: "拨弦", how: "左手奏低音，右手奏快速的旋律跑动。" }, { name: "敲击箱体（tamboreo）", how: "用手敲击共鸣箱（tamboreo）作为打击乐。" }, { name: "刮奏", how: "手指扫过琴弦。" }] },
"pito": { sound: "单薄、尖锐、明亮的哨音，起音生动。", range: "约一个半八度。", acoustics: "气息 → 风道 → 边棱 → 竹管或木管。", materials: "竹或木，带风道和几个指孔。", making: "竹或木，由本地工匠制作。", usage: "从管端吹奏，演奏者常同时击鼓。", role: "旋律。", players: "村庄乐师。", skills: "高音区带装饰的舞曲。", scenes: "村庄节庆和传统舞蹈。", repertoire: "配鼓的村庄舞曲。", origin: "墨西哥，原住民和梅斯蒂索乐师之间。", history: "一种小型竹制或木制哨笛，在村庄舞蹈中常与鼓搭配。", today: "仍活跃。", techniques: [{ name: "舞曲旋律", how: "一手吹奏尖锐带装饰的旋律，另一手击鼓。" }, { name: "颤音", how: "手指抖动，装饰旋律。" }] },
"tambora": { sound: "深沉轰鸣的鼓点，上面叠加钹的撞击声。", range: "无固定音高，低沉。", acoustics: "槌击 → 皮鼓面 → 木鼓身；顶上装有一片钹。", materials: "木制或金属鼓身，皮鼓面，鼓槌和一片小钹。", making: "两面蒙皮的木鼓身。", usage: "悬挂或放在架上，用鼓槌击鼓，用棍击钹。", role: "节奏与脉动。", players: "tamborazo 乐队的鼓手。", skills: "在铜管之下的切分后拍和重音。", scenes: "tamborazo 乐队、游行、婚礼和节庆。", repertoire: "萨卡特卡斯和哈利斯科的 tamborazo；banda。", origin: "墨西哥西北部和西部，源于欧洲的军用低音鼓。", history: "一种双面低音鼓，顶上常装一片小钹，是萨卡特卡斯和哈利斯科 tamborazo 乐队的核心。", today: "仍活跃。", techniques: [{ name: "槌击", how: "鼓槌击打鼓面，发出深沉的轰鸣。" }, { name: "击钹或击边", how: "鼓棍击打顶上的钹或鼓边，发出尖锐的重音。" }] },
"trutruka": { sound: "嘶哑、深沉、有力的铜管般呼声，有几个自然音，边缘明亮而粗犷。", range: "数个自然泛音。", acoustics: "唇振 → 长竹管 → 牛角喇叭口。", materials: "掏空的 colihue 竹，外缠马肠或羊毛，配牛角喇叭口。", making: "掏空的 colihue 竹，外缠马肠或羊毛，配牛角喇叭口。", usage: "斜向上举起，在窄端以嘴唇振动吹奏。", role: "信号与仪式。", players: "马普切（Mapuche）男子。", skills: "在自然泛音上吹出有力持续的呼声。", scenes: "ngillatun 典礼、palin 游戏和集会。", repertoire: "ngillatun 仪式音乐。", origin: "智利南部和阿根廷的马普切人。", history: "带牛角喇叭口的长竹号，在 ngillatun 和其他集会上演奏；长度可达数米。", today: "仍活跃。", techniques: [{ name: "泛音呼号", how: "嘴唇在竹号中振动，在自然泛音上吹出有力持续的呼声。" }, { name: "泛音间的唇滑奏", how: "收紧嘴唇，音色不间断地跳到上一个自然泛音。" }] },
"pifilka": { sound: "响亮穿透、尖锐的单音，边缘粗糙带嗡鸣。", range: "每管一个音。", acoustics: "气息 → 边棱 → 闭口木管。", materials: "雕刻的木，有时用陶。", making: "木头雕成。", usage: "对着闭口管的顶端吹，短促地反复吹响。", role: "信号与仪式。", players: "成对的舞者。", skills: "在演奏者之间交替吹出节奏性的号声。", scenes: "ngillatun 典礼和舞蹈。", repertoire: "ngillatun 仪式。", origin: "智利南部和阿根廷的马普切人。", history: "一种带一两根管的木制闭口哨，每管发出一个响亮穿透的音；舞者在仪式中成对吹奏。", today: "仍活跃。", techniques: [{ name: "短促吹响", how: "一口急促的气息吹过闭口管，发出尖锐的单音爆发。" }, { name: "交替吹响", how: "两位演奏者交替吹出快速的号声，交错成一个节奏。" }] },
"kull-kull": { sound: "嘶哑深沉的兽角呼声。", range: "一两个自然音。", acoustics: "唇振 → 牛角。", materials: "牛角。", making: "侧面开有吹口的牛角。", usage: "以嘴唇振动吹过靠近尖端的孔。", role: "信号。", players: "马普切男子。", skills: "在一两个音上吹出有力的呼声。", scenes: "召集集会、ngillatun 典礼。", origin: "智利南部和阿根廷的马普切人。", history: "从侧孔吹奏的牛角号，用于召集人们集会和典礼。", today: "仍活跃。", techniques: [{ name: "信号呼号", how: "唇在窄端振动，发出一声响亮的铜管号声。" }, { name: "泛音间的唇滑奏", how: "收紧嘴唇，音色不间断地跳到上一个自然泛音。" }] },
"trompe": { sound: "柔和、弹拨感、嗡鸣的音色，泛音由口腔塑形，像低语的旋律。", range: "一个基音的泛音。", acoustics: "拨弹 → 金属簧舌 → 口腔。", materials: "金属框配钢制簧舌。", making: "锻造的金属框配钢制簧舌。", usage: "抵在微张的牙齿上，用手指拨弹簧舌，由口腔塑造泛音。", role: "独奏旋律。", players: "马普切男女。", skills: "改变口型来选取泛音，通过乐器呼吸以造成节奏。", scenes: "个人音乐、求爱、集会。", repertoire: "个人歌曲和求爱。", origin: "欧洲；金属口簧在接触之后经贸易传到马普切人，成为他们自己的乐器。", history: "西班牙人到来后被采用，马普切男女用它演奏个人歌曲和求爱。", today: "仍活跃。", techniques: [{ name: "拨弹簧舌", how: "手指拨弹钢簧舌，发出弹拨感的持续低音。" }, { name: "选取泛音", how: "改变口型，把泛音挑出来作为持续音之上的旋律。" }, { name: "气息节奏", how: "通过乐器呼出和吸入，增添节奏和起伏。" }] },
"kaskawilla": { sound: "明亮的叮当声，随每一摇而响。", range: "无固定音高，高。", acoustics: "摇动 → 带丸的铃。", materials: "青铜或黄铜铃，系在皮带或箍上。", making: "金属铃系在皮带上。", usage: "手摇或舞蹈时佩戴。", role: "节奏。", players: "舞者。", skills: "随 kultrun 鼓点节奏地摇动。", scenes: "ngillatun 和 machi 治疗典礼。", origin: "马普切人，源于西班牙的 cascabel（雪橇铃）。", history: "串在皮带或环上的小金属铃，在仪式舞蹈中摇动。", today: "仍活跃。", techniques: [{ name: "稳定摇动", how: "配合舞蹈或歌唱摇动，各部件撞击出干脆利落的节奏。" }, { name: "连续摇动", how: "不停地快速摇动，叮当声模糊成持续闪烁的沙沙声。" }] },
"nolkin": { sound: "嘶哑、粗犷、带鼻音的号角声，由吸气产生；呼声短促。", range: "几个自然音。", acoustics: "吸气时的唇振 → 空心植物茎 → 角制喇叭口。", materials: "类似蓟的空心茎，配牛角喇叭口。", making: "空心植物茎配角制喇叭口。", usage: "演奏者通过口端把空气向内吸入。", role: "信号与仪式。", players: "马普切男子。", skills: "吸气发声，短促重复的呼声。", scenes: "典礼和集会。", origin: "智利南部和阿根廷的马普切人。", history: "用空心植物茎配角制喇叭口做成的号；不同寻常的是，它靠吸气而非吹气来演奏。", today: "仍存在但罕见。", techniques: [{ name: "吸气发声", how: "空气从口端向内吸入，发出刺耳嗡鸣的音。" }, { name: "重复呼号", how: "短促重复的吸气形成脉动的呼声。" }] },
"kultrun": { sound: "深沉温暖共鸣的鼓点，起音柔和，音体鸣响；鼓内的小物件随每一击沙沙作响。", range: "无固定音高，中低。", acoustics: "槌击 → 皮鼓面 → 木碗。", materials: "雕刻的木碗配皮鼓面，内含小物件，用鼓槌击打。", making: "雕刻的木碗配皮鼓面；内放小圣物，鼓面绘有四个方位。", usage: "一手举起，machi 唱歌时用一根鼓槌击打。", role: "节奏与仪式。", players: "machi（治疗师），常为女性。", skills: "稳定且逐渐加速的鼓点，引导出神和祈祷。", scenes: "machi 治疗仪式（machitun）、ngillatun 典礼。", repertoire: "machi 治疗仪式和 ngillatun。", meaning: "宇宙的模型；鼓把 machi 带往灵界。", origin: "智利南部和阿根廷的马普切人。", history: "一种浅碗形的鼓，是 machi 治疗师的神圣乐器；其彩绘鼓面表现四个方位和宇宙。", today: "仍活跃；是马普切身份认同的象征。", techniques: [{ name: "稳定节拍", how: "一根鼓槌以均匀的脉动在 machi 的歌声之下击打鼓面。" }, { name: "加速滚奏", how: "击打逐渐加快，成为急促隆隆的滚奏，通向出神状态。" }] },
"kunkulkawe": { sound: "柔和、嗡鸣、低语般的音色，轻柔的泛音由口腔塑形。", range: "一个基音的泛音。", acoustics: "一张弓与另一张弓的摩擦 → 弦 → 口腔。", materials: "两张小木弓，以马尾为弦。", making: "两张木与马尾制成的小弓。", usage: "一张弓抵在嘴边，另一张摩擦其弦；口型为声音着色。", role: "独奏旋律。", players: "马普切人个人，用于个人音乐。", skills: "摩擦以得到颤动的持续音，用口塑造泛音。", scenes: "个人音乐和典礼。", origin: "智利南部和阿根廷的马普切人。", history: "一对小弓，一张摩擦另一张，弦靠近嘴边，嘴起共鸣器的作用。", today: "罕见。", techniques: [{ name: "摩擦", how: "用一张弓摩擦另一张弓的弦，得到颤动持续的嗡鸣。" }, { name: "口型泛音", how: "在弓上方改变口型来选取泛音。" }] },
"capador": { sound: "带气息、空灵、空洞的音色；在管列上快速上下跑动，听来像一阵哨声。", range: "约一个八度。", tuning: "管按长度切割。", acoustics: "气息吹过敞口管顶 → 闭口竹管。", materials: "竹管捆成一排。", making: "竹管捆成一排。", usage: "抵在下唇上，吹奏时来回移动。", role: "信号与旋律。", players: "走街串巷的阉畜匠（capadores）。", skills: "快速的音阶跑动和颤动的气息重音。", scenes: "乡村节庆和街头吆喝。", origin: "哥伦比亚高地，当地安第斯的原住民和梅斯蒂索人。", history: "一种单排竹排箫，传统上由走街串巷的阉畜匠（capadores）吹奏，用来宣告到来；穆伊斯卡人也演奏类似的排箫。", today: "罕见。", techniques: [{ name: "吹音", how: "气息吹过管口，得到带气息的音色。" }, { name: "快速扫奏", how: "管列在唇边快速掠过，奏出音阶跑动。" }, { name: "颤动气息", how: "颤动的气息形成搏动的重音。" }] },
"clay-flute": { sound: "柔和圆润、清澈的哨音，带空洞的色泽。", range: "约一个八度。", acoustics: "气息 → 风道 → 边棱 → 陶管。", materials: "烧制的陶土，带风道和指孔。", making: "模制烧成的陶土。", usage: "通过风道吹奏，向前平举。", role: "旋律。", skills: "带装饰的旋律和颤音。", scenes: "节庆和仪式。", origin: "哥伦比亚高地的穆伊斯卡人（Muisca）；其考古遗址中发现有陶笛。", finds: "穆伊斯卡考古遗址。", history: "烧制的管状陶制风道笛，有时带具象装饰，用于西班牙编年史家所描述的节庆中。", today: "已成历史。", techniques: [{ name: "吐音旋律", how: "舌头通过风道开始每个音，吐音清晰如哨。" }, { name: "颤音", how: "手指在孔上快速抖动，在相邻两个音高之间交替。" }] },
"bone-flute": { sound: "单薄、明亮、高亢、略带气息的音色。", range: "约一个八度。", acoustics: "气息 → 边棱 → 骨管。", materials: "鹿、鸟或其他动物的空心骨，开有几个孔。", making: "带指孔的动物骨或人骨。", usage: "从端部或通过缺口吹奏。", role: "旋律与信号。", players: "战士和仪式专家。", skills: "短促尖锐的旋律音型。", scenes: "战争仪式、宴会和舞蹈。", origin: "南美洲，包括穆伊斯卡人和图皮南巴人（Tupinambá）在内的许多民族。", finds: "让·德·莱里（Jean de Léry，1578年）有记述；南美洲各地都发现有骨笛。", history: "用动物骨制成的笛，据说图皮南巴人还用被杀敌人的骨头制笛，用于仪式和战争，让·德·莱里等编年史家都有记述。", today: "已成历史。", techniques: [{ name: "尖锐音型", how: "短促尖锐的气息吹出高亢尖锐的旋律音型。" }] },
"gold-bells": { sound: "细腻明亮的叮铃闪烁声，起音轻柔。", range: "无固定音高，高。", acoustics: "运动 → 金片与金铃相互撞击。", materials: "黄金或 tumbaga（金铜合金）。", making: "穆伊斯卡金匠以失蜡法铸造 tumbaga（金铜合金），或锤成薄片。", usage: "佩戴在身上或挂在权杖上，随运动鸣响。", role: "装饰与仪式之声。", players: "贵族和舞者。", skills: "借舞蹈产生有节奏的闪烁声。", scenes: "节庆和典礼。", origin: "哥伦比亚高地的穆伊斯卡人，tumbaga（金铜合金）的金匠大师。", finds: "波哥大黄金博物馆（Museo del Oro）所藏穆伊斯卡金器。", history: "小金片和金铃挂在饰物、鼻饰和衣服上，节庆中随佩戴者的动作而鸣响。", today: "已成历史。", techniques: [{ name: "叮当作响", how: "配合舞蹈或歌唱摇动，各部件撞击出干脆利落的节奏。" }, { name: "连续摇动", how: "不停地快速摇动，叮当声模糊成持续闪烁的沙沙声。" }] },
"fotuto": { sound: "深沉嘶哑、轰鸣的号角声。", range: "一两个音。", acoustics: "唇振 → 海螺、葫芦或陶管。", materials: "海螺壳、葫芦或烧制的陶土。", making: "海螺、葫芦或陶土。", usage: "以嘴唇振动吹奏。", role: "信号。", players: "传令官和战士。", skills: "响亮传远的呼声。", scenes: "节庆、战争和集会。", origin: "南美洲北部和加勒比；编年史家用这个词称呼穆伊斯卡人的号。", history: "西班牙人用来称呼该地区海螺、葫芦和陶制号角的名称；在穆伊斯卡人中用来宣告节庆与战争。", today: "已成历史。", uncertain: "西班牙人使用这个词比较随意，因此这种乐器的确切形制不明。", techniques: [{ name: "信号呼号", how: "唇在窄端振动，发出一声响亮的铜管号声。" }] },
"log-drum": { sound: "深沉空洞、轰鸣的鼓点，带木质感。", range: "无固定音高。", acoustics: "击打 → 皮鼓面 → 空心原木。", materials: "掏空的原木，配皮鼓面。", making: "掏空的原木，蒙皮鼓面。", usage: "放在地上，用手或槌击打。", role: "节奏。", skills: "稳定的节庆鼓点。", scenes: "节庆和舞蹈。", origin: "南美洲北部；放在这里是因为编年史家所描述的穆伊斯卡鼓的细节不详。", history: "带皮鼓面的掏空原木鼓在该地区很普遍；这一条目是泛称的替代。", today: "该地区仍有类似的鼓在使用。", uncertain: "这是泛称的替代；穆伊斯卡的鼓没有详细资料。", techniques: [{ name: "击打", how: "手或槌击打原木，发出深沉的木质轰鸣。" }, { name: "滚奏", how: "快速击打，形成隆隆的滚奏。" }] },
"urua": { sound: "非常低沉、丰满、带气息的嗡鸣音色，成对演奏，两个音高相互拍击。", range: "每支笛一两个音。", acoustics: "气息 → 边棱 → 极长的竹管。", materials: "带内部风道的长竹管。", making: "长竹管，常超过两米。", usage: "成对演奏，每位舞者持一支长笛边舞边吹。", role: "仪式音乐与舞蹈。", players: "成对起舞的男子。", skills: "两位演奏者之间交错的低音。", scenes: "典礼舞蹈。", repertoire: "上欣古的典礼。", origin: "巴西的原住民；这个名称以上欣古的卡马尤拉人（Kamayurá）和其他民族最为人所知。", history: "由起舞的男子成对演奏的极长竹笛；图皮南巴人的用法是重构的。", today: "在上欣古仍然活跃。", uncertain: "它在图皮南巴人中的使用是重构的。", techniques: [{ name: "交错低音", how: "两位演奏者各在自己的长笛上吹出一个低音，按某种型式交替。" }] },
"seed-rattle": { sound: "随每一步响起的柔和干燥的沙沙声。", range: "无固定音高。", acoustics: "运动 → 种荚相互撞击。", materials: "穿在绳上的干种荚或坚果壳。", making: "硬种荚或坚果壳串在绳上。", usage: "系在脚踝或膝上，靠跺脚发出沙沙声。", role: "节奏。", players: "舞者。", skills: "有节奏的跺脚步法。", scenes: "舞蹈和典礼。", origin: "巴西海岸和亚马孙的原住民。", finds: "让·德·莱里（1578年）有记述。", history: "一串串硬种荚或坚果壳戴在舞者的腿和臂上；莱里描述了佩戴它们的图皮南巴舞者。", today: "在许多原住民中仍然活跃。", techniques: [{ name: "跺脚摇响", how: "跺脚的步子摇动种荚，发出清脆的沙沙声。" }, { name: "连续沙沙声", how: "快速的脚步让种荚不停地沙沙作响。" }] },
"maraca": { sound: "干燥清脆、尖锐的沙沙声，起音快；旋转时发出连续的嘶嘶声。", range: "无固定音高。", acoustics: "摇动 → 葫芦内的种子或小石子。", materials: "装有种子或小石子的葫芦，木柄和羽毛。", making: "装满种子并装上手柄的葫芦，常以羽毛装饰。", usage: "手摇，配合歌唱与舞蹈的节奏。", role: "节奏与仪式。", players: "萨满（pajé），后来也有舞蹈乐手。", skills: "稳定的摇动、重音和震音滚奏。", scenes: "萨满仪式、舞蹈和治疗。", meaning: "被视为灵的声音；用来与灵界沟通。", origin: "巴西和巴拉圭的图皮–瓜拉尼诸民族；maraca 一词来自他们的语言。", finds: "汉斯·施塔登（Hans Staden）和让·德·莱里在16世纪有记述。", history: "pajé（萨满）的神圣葫芦摇铃，被认为能与灵对话；它作为 maraca 传入拉丁美洲音乐。", today: "仍活跃于原住民仪式和拉丁美洲音乐中。", techniques: [{ name: "稳定摇动", how: "每次摇动种子撞击葫芦壁，发出清脆的节拍。" }, { name: "震音滚奏", how: "快速连续地摇动，得到持续的沙沙声。" }] },
"taquara": { sound: "深沉嘶哑、轰鸣的音色，更偏木质而非铜管味。", range: "一两个音。", acoustics: "唇振或气息 → 竹管。", materials: "一节大竹子。", making: "截取的竹段。", usage: "在一端以嘴唇振动吹奏，或对着开口吹。", role: "信号与仪式。", skills: "深沉持续的音和呼声。", scenes: "宴会、舞蹈和战争。", origin: "巴西海岸的原住民；taquara 是图皮语中的“竹”。", history: "把竹段当作号或低音管来吹；编年史家提到图皮南巴人在宴会和战争中使用竹号。", today: "亚马孙的部分地区仍在演奏竹号。", techniques: [{ name: "持续音", how: "嘴唇振动，发出深沉持续的音。" }] },
"inubia": { sound: "意在吓人的响亮、嘶哑、刺耳的号声。", range: "一两个音。", acoustics: "唇振 → 管。", materials: "木、竹或葫芦，有时用羽毛装饰。", usage: "以嘴唇振动吹奏。", role: "信号。", players: "战士。", skills: "响亮的战争呼号。", scenes: "战争和集会。", origin: "巴西海岸的图皮–瓜拉尼诸民族。", finds: "16世纪早期造访巴西的欧洲人有所记载。", history: "用来召集战士和恐吓敌人的战号，早期的欧洲访客曾有记载。", today: "已成历史。", uncertain: "其确切的材料和形制没有很好的记录。", techniques: [{ name: "信号呼号", how: "唇在窄端振动，发出一声响亮的铜管号声。" }] },
"stamping-tubes": { sound: "深沉空洞、轰鸣的重击声，带短促的音高鸣响。", range: "音高大致由管长决定。", acoustics: "撞击地面 → 闭口竹管内的气柱。", materials: "一端封闭的竹管。", making: "按长度截取的竹管。", usage: "竖持，在地面上顿击。", role: "节奏。", players: "舞者。", skills: "随舞蹈稳定的顿击脉动。", scenes: "舞蹈和典礼。", origin: "南美洲的原住民；在这里代表图皮南巴舞蹈中的大鼓点。", history: "竹管撞击地面发出深沉空洞的重击声；亚马孙和沿海的若干民族使用它。", today: "在亚马孙的若干民族中仍然活跃。", techniques: [{ name: "顿击脉动", how: "敞口的底端撞击地面，发出空洞而有音高的重击。" }] },
});
